import 'my_tasks_tab.dart';
import 'projects_tab.dart';
import 'tasks_tab.dart';

/// Post-login shell. Shows only the tabs allowed for the user's role.
class HomeScreen extends ConsumerStatefulWidget {
  const HomeScreen({super.key});

  @override
  ConsumerState<HomeScreen> createState() => _HomeScreenState();
}

class _HomeScreenState extends ConsumerState<HomeScreen> {
  int _index = 0;

  static const _titles = {
    'projects': 'Projects',
    'members': 'Members',
    'tasks': 'Tasks',
    'mine': 'Assigned to me',
  };

  // Short labels for the bottom navigation bar.
  static const _navLabels = {
    'projects': 'Projects',
    'members': 'Members',
    'tasks': 'Tasks',
    'mine': 'Mine',
  };

  static const _icons = {
    'projects': Icons.folder_outlined,
    'members': Icons.people_outline,
    'tasks': Icons.checklist_outlined,
    'mine': Icons.person_outline,
  };

  @override
  Widget build(BuildContext context) {
    final user = ref.watch(currentUserProvider);
    return user.when(
      loading: () =>
          const Scaffold(body: Center(child: CircularProgressIndicator())),
      error: (e, _) => Scaffold(
        body: ErrorState(
          message: 'Could not load account: $e',
          onRetry: () => ref.invalidate(currentUserProvider),
        ),
      ),
      data: (account) {
        if (account == null) {
          return const Scaffold(body: Center(child: Text('Logged out.')));
        }
        final tabs = visibleTabs(account.role);
        final safeIndex = _index.clamp(0, tabs.length - 1);
        final scheme = Theme.of(context).colorScheme;
        return Scaffold(
          appBar: AppBar(
            title: Text(_titles[tabs[safeIndex]]!),
            actions: [
              Consumer(
                builder: (context, ref, _) {
                  final mode = ref.watch(themeModeProvider);
                  final icon = switch (mode) {
                    ThemeMode.light => Icons.light_mode_outlined,
                    ThemeMode.dark => Icons.dark_mode_outlined,
                    ThemeMode.system => Icons.brightness_auto_outlined,
                  };
                  return IconButton(
                    tooltip: 'Theme',
                    icon: Icon(icon),
                    onPressed: () => showThemePicker(context, ref),
                  );
                },
              ),
              PopupMenuButton<String>(
                tooltip: account.name,
                onSelected: (value) {
                  if (value == 'logout') {
                    logOut(ref);
                  }
                },
                itemBuilder: (context) => [
                  PopupMenuItem<String>(
                    enabled: false,
                    child: Row(
                      children: [
                        CircleAvatar(
                          backgroundColor: scheme.primaryContainer,
                          foregroundColor: scheme.onPrimaryContainer,
                          child: Text(initialsOf(account.name)),
                        ),
                        const SizedBox(width: 12),
                        Expanded(
                          child: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            mainAxisSize: MainAxisSize.min,
                            children: [
                              Text(
                                account.name,
                                style: const TextStyle(
                                  fontWeight: FontWeight.w600,
                                ),
                                overflow: TextOverflow.ellipsis,
                              ),
                              Text(
                                account.email,
                                style: TextStyle(
                                  fontSize: 12,
                                  color: scheme.onSurfaceVariant,
                                ),
                                overflow: TextOverflow.ellipsis,
                              ),
                            ],
                          ),
                        ),
                      ],
                    ),
                  ),
                  const PopupMenuDivider(),
                  const PopupMenuItem<String>(
                    value: 'logout',
                    child: Row(
                      children: [
                        Icon(Icons.logout),
                        SizedBox(width: 12),
                        Text('Log out'),
                      ],
                    ),
                  ),
                ],
                child: Padding(
                  padding: const EdgeInsets.symmetric(horizontal: 8),
                  child: CircleAvatar(
                    backgroundColor: scheme.primaryContainer,
                    foregroundColor: scheme.onPrimaryContainer,
                    child: Text(initialsOf(account.name)),
                  ),
                ),
              ),
              const SizedBox(width: 4),
            ],
          ),
          body: _body(tabs[safeIndex]),
          bottomNavigationBar: NavigationBar(
            selectedIndex: safeIndex,
            onDestinationSelected: (i) => setState(() => _index = i),
            destinations: [
              for (final tab in tabs)
                NavigationDestination(
                  icon: Icon(_icons[tab]),
                  label: _navLabels[tab]!,
                ),
            ],
          ),
        );
      },
    );
  }

  Widget _body(String tab) {
    switch (tab) {
      case 'projects':
        return const ProjectsTab();
      case 'members':
        return const MembersTab();
      case 'mine':
        return const MyTasksTab();
      case 'tasks':
      default:
        return const TasksTab();
    }
  }
}

"""Business rules ÔÇö server-side port of task_planner/lib/core/rules.dart.

The server is the enforcer; the Dart copy stays as a UX-side check only.
"""
from .errors import AssignmentError, RuleError

# Roles (cumulative: admin > project owner > user).
ADMIN = "admin"
PROJECT_OWNER = "project_owner"
USER = "user"
ROLES = (ADMIN, PROJECT_OWNER, USER)

# Membership states.
PENDING = "pending"
ACTIVE = "active"

# Task states and priorities.
TASK_TODO = "todo"
TASK_COMPLETED = "completed"
PRIORITIES = ("low", "medium", "high")


def can_log_in(status: str) -> bool:
    """Only active accounts may log in; pending accounts await approval."""
    return status == ACTIVE


def is_admin(role: str) -> bool:
    return role == ADMIN


def is_owner_or_admin(role: str) -> bool:
    return role in (ADMIN, PROJECT_OWNER)


def require_admin(role: str) -> None:
    if not is_admin(role):
        raise RuleError("Only an admin can do this.")


def require_owner_or_admin(role: str) -> None:
    if not is_owner_or_admin(role):
        raise RuleError("Only a project owner or admin can do this.")


def validate_task_assignment(
    task_project_id: int, assignee_id: int | None, assignee_project_id: int | None
) -> None:
    """A task is assigned to its project (None) or one same-project person."""
    if assignee_id is not None and assignee_project_id != task_project_id:
        raise AssignmentError("Assignee must belong to the task project.")


def require_project_access(
    role: str, actor_project_id: int | None, project_id: int
) -> None:
    """Admins manage any project; everyone else only their own."""
    if not is_admin(role) and actor_project_id != project_id:
        raise RuleError("You can only manage your own project tasks.")

