16:   Future<Task> createTask({
17:     required int projectId,
18:     required String title,
19:     String? description,
20:     String priority = 'medium',
21:     DateTime? dueDate,
22:     int? assigneeId,
23:   }) async {
24:     final json = await _client.post('/tasks', {
25:       'project_id': projectId,
26:       'title': title,
27:       'description': ?description,
28:       'priority': priority,
29:       'due_date': ?_dateOnly(dueDate),
30:       'assignee_id': ?assigneeId,
31:     });
32:     DataSync.instance.ping();
33:     return Task.fromJson(json as Map<String, dynamic>);
34:   }
35: 
36:   /// Partial edit. Null [description], [dueDate], and [assigneeId] clear
37:   /// those fields; [projectId] never changes after creation.
38:   Future<Task> updateTask({
39:     required int taskId,
40:     required String title,
41:     String? description,
42:     required String priority,
43:     DateTime? dueDate,
44:     int? assigneeId,
45:   }) async {
46:     final json = await _client.patch('/tasks/$taskId', {
47:       'title': title,
48:       'description': description,
49:       'priority': priority,
50:       'due_date': _dateOnly(dueDate),
51:       'assignee_id': assigneeId,
52:     });
53:     DataSync.instance.ping();
54:     return Task.fromJson(json as Map<String, dynamic>);
