import fs from 'node:fs';

const BASE = 'http://127.0.0.1:60074';

export async function connect() {
  const targets = await (await fetch(`${BASE}/json/list`)).json();
  const page = targets.find((t) => t.type === 'page' && t.url.includes('63787'))
    || targets.find((t) => t.type === 'page');
  if (!page) throw new Error('No page target found');
  const ws = new WebSocket(page.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => {
    ws.onopen = resolve;
    ws.onerror = (event) => reject(new Error(`WebSocket error: ${event.message ?? 'unknown'}`));
  });
  let nextId = 0;
  const pending = new Map();
  ws.onmessage = (event) => {
    const message = JSON.parse(event.data);
    if (message.id && pending.has(message.id)) {
      const { resolve, reject } = pending.get(message.id);
      pending.delete(message.id);
      if (message.error) reject(new Error(JSON.stringify(message.error)));
      else resolve(message.result);
    }
  };
  const send = (method, params = {}) => new Promise((resolve, reject) => {
    const id = ++nextId;
    pending.set(id, { resolve, reject });
    ws.send(JSON.stringify({ id, method, params }));
  });
  return { send, ws, page };
}

export async function evaluate(send, expression) {
  const result = await send('Runtime.evaluate', {
    expression,
    awaitPromise: true,
    returnByValue: true,
    userGesture: true,
  });
  if (result.exceptionDetails) {
    throw new Error(JSON.stringify(result.exceptionDetails, null, 2));
  }
  return result.result.value;
}

export async function screenshot(send, path) {
  const { data } = await send('Page.captureScreenshot', { format: 'png' });
  fs.writeFileSync(path, Buffer.from(data, 'base64'));
  return path;
}

export async function clickAt(send, x, y) {
  await send('Input.dispatchMouseEvent', { type: 'mouseMoved', x, y });
  await send('Input.dispatchMouseEvent', { type: 'mousePressed', x, y, button: 'left', clickCount: 1 });
  await send('Input.dispatchMouseEvent', { type: 'mouseReleased', x, y, button: 'left', clickCount: 1 });
}

export async function typeText(send, text) {
  await send('Input.insertText', { text });
}

export async function pressKey(send, key, code = key, keyCode = 0) {
  await send('Input.dispatchKeyEvent', { type: 'keyDown', key, code, windowsVirtualKeyCode: keyCode });
  await send('Input.dispatchKeyEvent', { type: 'keyUp', key, code, windowsVirtualKeyCode: keyCode });
}

export async function enableSemantics(send) {
  return evaluate(send, `(() => {
    const placeholder = document.querySelector('flt-semantics-placeholder');
    if (!placeholder) return 'already-enabled-or-missing';
    placeholder.click();
    return 'clicked';
  })()`);
}

export async function semanticsSnapshot(send) {
  return evaluate(send, `(() => {
    const nodes = [...document.querySelectorAll('flt-semantics')];
    return nodes.map((el) => {
      const rect = el.getBoundingClientRect();
      return {
        role: el.getAttribute('role'),
        label: (el.getAttribute('aria-label') || '').trim(),
        text: (el.textContent || '').trim().slice(0, 80),
        tappable: el.hasAttribute('flt-tappable'),
        x: Math.round(rect.x + rect.width / 2),
        y: Math.round(rect.y + rect.height / 2),
        w: Math.round(rect.width),
        h: Math.round(rect.height),
      };
    }).filter((n) => n.label || n.text || n.tappable);
  })()`);
}

export async function clickSemantics(send, matcher, options = {}) {
  const node = await evaluate(send, `(() => {
    const nodes = [...document.querySelectorAll('flt-semantics')];
    const re = new RegExp(${JSON.stringify(matcher)});
    for (const el of nodes) {
      const label = (el.getAttribute('aria-label') || '').trim();
      const text = (el.textContent || '').trim();
      if (re.test(label) || re.test(text)) {
        const rect = el.getBoundingClientRect();
        if (rect.width === 0 || rect.height === 0) continue;
        return { x: rect.x + rect.width / 2, y: rect.y + rect.height / 2, label, text };
      }
    }
    return null;
  })()`);
  if (!node) throw new Error(`No semantics node matching ${matcher}`);
  await clickAt(send, node.x, node.y);
  return node;
}

export const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

import { connect, evaluate, enableSemantics, semanticsSnapshot, screenshot, sleep } from './cdp.mjs';

const { send } = await connect();
console.log('page:', await evaluate(send, `({ url: location.href, title: document.title, bodyText: document.body.innerText.slice(0, 300) })`));
console.log('placeholder:', await evaluate(send, `!!document.querySelector('flt-semantics-placeholder')`));
console.log('enable:', await enableSemantics(send));
