import { connect, evaluate, clickAt, typeText, sleep, screenshot } from './cdp.mjs';

const { send } = await connect();
const shot = (name) => screenshot(send, `C:/Users/CHEDI/AppData/Local/Temp/opencode/e2e/${name}.png`);

async function rectOf(selector) {
  const rect = await evaluate(send, `(() => {
    const el = document.querySelector(${JSON.stringify(selector)});
    if (!el) return null;
    const r = el.getBoundingClientRect();
    if (r.width === 0 || r.height === 0) return null;
    return { x: r.x + r.width / 2, y: r.y + r.height / 2 };
  })()`);
  if (!rect) throw new Error(`Missing visible ${selector}`);
  return rect;
}

async function clickText(text) {
  const rect = await evaluate(send, `(() => {
    const re = new RegExp(${JSON.stringify(text)});
    for (const el of document.querySelectorAll('flt-semantics')) {
      if (!el.hasAttribute('flt-tappable')) continue;
      if (re.test(el.textContent.trim()) || re.test(el.getAttribute('aria-label') || '')) {
        const r = el.getBoundingClientRect();
        if (r.width && r.height) return { x: r.x + r.width / 2, y: r.y + r.height / 2, text: el.textContent.trim() };
      }
    }
    return null;
  })()`);
  if (!rect) throw new Error(`No tappable node matching ${text}`);
  await clickAt(send, rect.x, rect.y);
  return rect;
}

async function fill(label, text) {
  const { x, y } = await rectOf(`input[aria-label="${label}"]`);
  await clickAt(send, x, y);
  await sleep(250);
  await typeText(send, text);
  await sleep(250);
  return evaluate(send, `document.querySelector('input[aria-label="${label}"]').value`);
}

async function dump(tag) {
  const info = await evaluate(send, `({
    url: location.href,
    text: [...document.querySelectorAll('flt-semantics')].map(e => (e.getAttribute('aria-label') || '') + '|' + e.textContent.trim()).filter(Boolean).join('\\n').slice(0, 2500),
    inputs: [...document.querySelectorAll('input')].map(e => e.getAttribute('aria-label') + '=' + e.value),
  })`);
  console.log(`--- ${tag} ---`);
  console.log(info.url);
  console.log(info.inputs.join(', '));
  console.log(info.text);
  await shot(tag);
}

