import { connect, clickAt, evaluate, screenshot, sleep, typeText } from './cdp.mjs';

const { send } = await connect();
let step = 0;

export async function shot(name) {
  step += 1;
  const file = `C:/Users/CHEDI/AppData/Local/Temp/opencode/e2e/${String(step).padStart(2, '0')}-${name}.png`;
  await screenshot(send, file);
  return file;
}

export function textQuery() {
  return evaluate(send, `({
    url: location.href,
    nodes: [...document.querySelectorAll('flt-semantics')].map(el => ({
      label: el.getAttribute('aria-label') || '',
      text: el.textContent.trim(),
      tappable: el.hasAttribute('flt-tappable'),
      role: el.getAttribute('role'),
      rect: (() => { const r = el.getBoundingClientRect(); return [r.x, r.y, r.width, r.height]; })(),
    })).filter(n => (n.label || n.text) && n.rect[2] > 0 && n.rect[3] > 0),
    inputs: [...document.querySelectorAll('input,textarea')].map(el => ({
      label: el.getAttribute('aria-label') || '',
      value: el.value,
      rect: (() => { const r = el.getBoundingClientRect(); return [r.x, r.y, r.width, r.height]; })(),
    })),
  })`);
}

export async function pageText() {
  const info = await textQuery();
  return `${info.url}\n${info.nodes.map((n) => `${n.label}|${n.text}`).join('\n')}`;
}

export async function assertText(pattern, message) {
  const text = await pageText();
  if (!new RegExp(pattern, 'i').test(text)) {
    throw new Error(`ASSERT FAILED (${message}): /${pattern}/ not found in:\n${text.slice(0, 2500)}`);
  }
  return true;
}

export async function waitForText(pattern, timeoutMs = 10000) {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    const text = await pageText();
    if (new RegExp(pattern, 'i').test(text)) return true;
    await sleep(300);
  }
  throw new Error(`TIMEOUT waiting for /${pattern}/ in:\n${(await pageText()).slice(0, 2500)}`);
}

async function findNode({ text, label, tappable = true, nth = 0, within = null }) {
  const result = await evaluate(send, `(() => {
    const reText = ${text ? `new RegExp(${JSON.stringify(text)})` : 'null'};
    const reLabel = ${label ? `new RegExp(${JSON.stringify(label)})` : 'null'};
    const within = ${JSON.stringify(within)};
    let count = 0;
    for (const el of document.querySelectorAll('flt-semantics')) {
      if (${tappable} && !el.hasAttribute('flt-tappable')) continue;
      const t = el.textContent.trim();
      const l = el.getAttribute('aria-label') || '';
      if (reText && !reText.test(t)) continue;
      if (reLabel && !reLabel.test(l)) continue;
      const r = el.getBoundingClientRect();
      if (!r.width || !r.height) continue;
      if (within && !(r.y >= within[1] - 4 && r.y <= within[1] + within[3] + 4)) continue;
      if (count === ${nth}) return { x: r.x + r.width / 2, y: r.y + r.height / 2, text: t, label: l };
      count += 1;
    }
    return null;
  })()`);
  if (!result) throw new Error(`No node text=${text} label=${label} nth=${nth}`);
  await clickAt(send, result.x, result.y);
  return result;
}

export async function clickText(pattern, options = {}) {
  return findNode({ text: pattern, ...options });
}

export async function clickLabel(pattern, options = {}) {
  return findNode({ label: pattern, text: null, ...options });
}

export async function fill(label, value) {
  const rect = await evaluate(send, `(() => {
    const el = document.querySelector('input[aria-label=' + ${JSON.stringify(JSON.stringify(label))} + '],textarea[aria-label=' + ${JSON.stringify(JSON.stringify(label))} + ']');
    if (!el) return null;
    const r = el.getBoundingClientRect();
    if (!r.width || !r.height) return null;
    return { x: r.x + r.width / 2, y: r.y + r.height / 2 };
  })()`);
  if (!rect) throw new Error(`No input labelled ${label}`);
  await clickAt(send, rect.x, rect.y);
  await sleep(250);
  await typeText(send, value);
  await sleep(250);
  const actual = await evaluate(send, `(() => {
    const el = document.querySelector('input[aria-label=' + ${JSON.stringify(JSON.stringify(label))} + '],textarea[aria-label=' + ${JSON.stringify(JSON.stringify(label))} + ']');
    return el ? el.value : null;
  })()`);
  if (actual !== value) throw new Error(`Fill ${label} expected ${value!r}, got ${actual}`);
  return actual;
}

export async function selectDropdown(label, option) {
  const dropdown = await evaluate(send, `(() => {
    const re = new RegExp(${JSON.stringify(label)});
    for (const el of document.querySelectorAll('flt-semantics')) {
      const t = el.textContent.trim();
      const l = el.getAttribute('aria-label') || '';
      if (!re.test(t) && !re.test(l)) continue;
      if (!el.hasAttribute('flt-tappable') && el.getAttribute('role') !== 'button') continue;
      const r = el.getBoundingClientRect();
      if (!r.width || !r.height) continue;
      return { x: r.x + r.width / 2, y: r.y + r.height / 2, text: t, label: l };
    }
    return null;
  })()`);
  if (!dropdown) throw new Error(`No dropdown ${label}`);
  await clickAt(send, dropdown.x, dropdown.y);
  await sleep(600);
  await clickText(`^${option}$`, { tappable: false });
  await sleep(600);
}

export async function login(email, password) {
  await waitForText('Log in');
  await fill('Email', email);
  await fill('Password', password);
  await clickText('^Log in$');
  await sleep(1500);
}

export { send, sleep, evaluate };

