import { clickText, fill, pageText, shot, sleep, waitForText } from './lib.mjs';
import { connect, evaluate } from './cdp.mjs';

const { send } = await connect();

async function domClick(pattern) {
  const clicked = await evaluate(send, `(() => {
    const re = new RegExp(${JSON.stringify(pattern)});
    for (const el of document.querySelectorAll('flt-semantics[flt-tappable]')) {
      if (re.test(el.textContent.trim()) || re.test(el.getAttribute('aria-label') || '')) { el.click(); return el.textContent.trim(); }
    }
    return null;
  })()`);
  return clicked;
}

