import {
  assertText, clickLabel, clickText, fill, pageText, selectDropdown,
  shot, sleep, waitForText,
} from './lib.mjs';
import { connect, evaluate } from './cdp.mjs';

const { send } = await connect();

async function waitForInput(label, timeoutMs = 10000) {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    const found = await evaluate(send, `!!document.querySelector('input[aria-label="${label}"],textarea[aria-label="${label}"]')`);
    if (found) return true;
    await sleep(250);
  }
  throw new Error(`TIMEOUT waiting for input ${label}`);
}

async function waitForGone(label, timeoutMs = 10000) {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    const found = await evaluate(send, `!!document.querySelector('input[aria-label="${label}"],textarea[aria-label="${label}"]')`);
    if (!found) return true;
    await sleep(250);
  }
  throw new Error(`TIMEOUT waiting for input ${label} to disappear`);
}

async function enableSemantics() {
  const sem = await evaluate(send, `document.querySelectorAll('flt-semantics').length`);
  if (sem > 0) return;
  for (let i = 0; i < 30; i += 1) {
    const clicked = await evaluate(send, `(() => { const p = document.querySelector('flt-semantics-placeholder'); if (p) { p.click(); return true; } return false; })()`);
    if (clicked) break;
    await sleep(1000);
  }
  await sleep(800);
}

