import fs from 'node:fs';

const API = 'http://localhost:8000/api/v1';

async function call(method, path, body, token) {
  const response = await fetch(`${API}${path}`, {
    method,
    headers: {
      'Content-Type': 'application/json',
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
    },
    body: body ? JSON.stringify(body) : undefined,
  });
  const text = await response.text();
  let json = null;
  try { json = text ? JSON.parse(text) : null; } catch { json = text; }
  if (!response.ok) throw new Error(`${method} ${path} -> ${response.status}: ${text}`);
  return { status: response.status, json };
}

const login = await call('POST', '/auth/login', { email: 'admin@e2e.test', password: 'Passw0rd!23' });
const adminToken = login.json.access_token;
const adminId = login.json.account.id;
console.log('admin id', adminId);

const projects = (await call('GET', '/projects')).json;
let alpha = projects.find((p) => p.name === 'Alpha');
let beta = projects.find((p) => p.name === 'Beta');
if (!beta) {
  beta = (await call('POST', '/projects', { name: 'Beta', description: 'Second project' }, adminToken)).json;
  console.log('beta created', beta.id);
}

const members = (await call('GET', '/members', null, adminToken)).json;
async function ensureMember(name, email, projectId) {
  let member = members.find((m) => m.email === email);
  if (!member) {
    member = (await call('POST', '/members', {
      name, email, password: 'Passw0rd!23', position: name === 'Alice' ? 'Lead' : 'Developer', project_id: projectId, role: 'user',
    }, adminToken)).json;
    console.log(`${name} created`, member.id);
  }
  return member;
}

const alice = await ensureMember('Alice', 'alice@e2e.test', alpha.id);
const bob = await ensureMember('Bob', 'bob@e2e.test', alpha.id);
const bruno = await ensureMember('Bruno', 'bruno@e2e.test', beta.id);

if (!alpha.owner_id) {
  alpha = (await call('POST', `/projects/${alpha.id}/assign-owner`, { owner_id: alice.id }, adminToken)).json;
  console.log('alpha owner', alpha.owner_id);
}
if (!beta.owner_id) {
  beta = (await call('POST', `/projects/${beta.id}/assign-owner`, { owner_id: bruno.id }, adminToken)).json;
  console.log('beta owner', beta.owner_id);
}

const accounts = (await call('GET', '/members', null, adminToken)).json;
const carol = accounts.find((a) => a.email === 'carol@e2e.test');
if (!carol) {
  const signup = await call('POST', '/auth/signup', {
    name: 'Carol', email: 'carol@e2e.test', password: 'Passw0rd!23', position: 'Designer', project_id: alpha.id,
  });
  console.log('carol signup', signup.status, signup.json.status);
}

