import { connect, evaluate, clickAt, typeText, screenshot, sleep } from './cdp.mjs';
const { send } = await connect();

async function clickAndType(x, y, text, timeoutMs = 60000) {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    await clickAt(send, x, y);
    await sleep(600);
    const active = await evaluate(send, `document.activeElement ? document.activeElement.tagName : ''`);
    if (active === 'INPUT' || active === 'TEXTAREA') {
      await typeText(send, text);
      await sleep(300);
      const value = await evaluate(send, `document.activeElement.value`);
      if (value === text) return true;
    }
    await sleep(800);
  }
  throw new Error(`No field at ${x},${y}`);
}

export async function loginFresh(email, password) {
  await send('Page.enable');
  await send('Page.reload', { ignoreCache: false });
  await clickAndType(520, 382, email);
  await clickAndType(520, 442, password);
  await clickAt(send, 520, 510);
  const deadline = Date.now() + 60000;
  while (Date.now() < deadline) {
    const url = await evaluate(send, `location.href`);
    if (url.includes('/home')) return true;
    await sleep(500);
  }
  throw new Error('Login did not reach /home');
}

