    const group = [...document.querySelectorAll('flt-semantics')].find(el => (el.getAttribute('aria-label') || '').startsWith(${JSON.stringify(prefix)}));
    if (!group) return { error: 'no group' };
    const g = group.getBoundingClientRect();
    const nodes = [...document.querySelectorAll(${JSON.stringify(kind === 'checkbox' ? 'flt-semantics[role="checkbox"]' : 'flt-semantics[flt-tappable]')})];
    for (const el of nodes) {
      const r = el.getBoundingClientRect();
      if (r.x >= g.x - 2 && r.x <= g.x + g.width + 2 && r.y >= g.y - 2 && r.y <= g.y + g.height + 2) {
        const isDelete = kind === 'delete' && el.textContent.trim() === 'Delete';
        const isCheckbox = kind === 'checkbox' && el.getAttribute('role') === 'checkbox' && !el.getAttribute('aria-label');
        if (isDelete || isCheckbox) {
          return { x: r.x + r.width / 2, y: r.y + r.height / 2, w: r.width, h: r.height };
        }
      }
    }
    return { error: 'no action' };
