async function rowCheckbox(prefix) {
  const point = await evaluate(send, `(() => {
    const group = [...document.querySelectorAll('flt-semantics')].find(el => (el.getAttribute('aria-label') || '').startsWith(${JSON.stringify(prefix)}));
    if (!group) return { error: 'no group' };
    const g = group.getBoundingClientRect();
    for (const el of document.querySelectorAll('flt-semantics[role="checkbox"]')) {
      const r = el.getBoundingClientRect();
      if (!el.getAttribute('aria-label') && r.x >= g.x - 2 && r.x <= g.x + g.width + 2 && r.y >= g.y - 2 && r.y <= g.y + g.height + 2) {
        return { x: r.x + r.width / 2, y: r.y + r.height / 2, rowY: r.y };
      }
    }
    return { error: 'no checkbox' };
  })()`);
  if (point.error) throw new Error(`${prefix}: ${point.error}`);
  if (point.y > 570) throw new Error(`${prefix}: checkbox offscreen at y=${point.y}`);
