const API = 'http://localhost:8000/api/v1';

async function call(method, path, { token, body } = {}) {
  const response = await fetch(`${API}${path}`, {
    method,
    headers: {
      'Content-Type': 'application/json',
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
    },
    body: body ? JSON.stringify(body) : undefined,
  });
  const text = await response.text();
  let json = null;
  try { json = text ? JSON.parse(text) : null; } catch { json = text; }
  return { status: response.status, body: text, json };
}

async function login(email) {
  const result = await call('POST', '/auth/login', {
    body: { email, password: 'Passw0rd!23' },
  });
  if (result.status !== 200) throw new Error(`${email} login ${result.status}: ${result.body}`);
  return result.json.access_token;
}

const failures = [];
function check(label, result, expected, forbidden = []) {
  const ok = Array.isArray(expected) ? expected.includes(result.status) : result.status === expected;
  const leaked = forbidden.filter((needle) => result.body.includes(needle));
  const safe = leaked.length === 0;
  console.log(`${ok && safe ? 'PASS' : 'FAIL'} | ${label} | status ${result.status} | ${result.body.slice(0, 120)}`);
  if (!ok) failures.push(`${label}: expected ${expected}, got ${result.status}`);
  if (!safe) failures.push(`${label}: leaked ${leaked.join(', ')}`);
}

const bruno = await login('bruno@e2e.test');
const alice = await login('alice@e2e.test');

const alphaTitles = ['Project kickoff', 'Today standup edited', 'Bob review', 'High priority fix', 'Overdue report'];

check('Bruno reads Alpha tasks', await call('GET', '/tasks?project_id=1', { token: bruno }), 403, alphaTitles);
check('Bruno reads Bob (Alpha) tasks by assignee', await call('GET', '/tasks?assignee_id=3', { token: bruno }), 403, alphaTitles);
check('Bruno creates a task in Alpha', await call('POST', '/tasks', { token: bruno, body: { project_id: 1, title: 'Cross project write', priority: 'medium' } }), 403);
check('Bruno edits Alpha task 1', await call('PATCH', '/tasks/1', { token: bruno, body: { title: 'Hijacked' } }), 403, alphaTitles);
check('Bruno completes Alpha task 1', await call('PATCH', '/tasks/1/complete', { token: bruno }), 403, alphaTitles);
check('Bruno deletes Alpha task 1', await call('DELETE', '/tasks/1', { token: bruno }), 403, alphaTitles);
check('Bruno creates a member in Alpha', await call('POST', '/members', { token: bruno, body: { name: 'Mallory', email: 'mallory@e2e.test', password: 'Passw0rd!23', project_id: 1, role: 'user' } }), [400, 403]);
check('Bruno confirms Alpha member Carol', await call('POST', '/members/5/confirm', { token: bruno }), [400, 403]);
check('Bruno grants admin to Alice', await call('POST', '/members/2/role', { token: bruno, body: { role: 'admin' } }), 403);

const brunoMembers = await call('GET', '/members', { token: bruno });
check('Bruno lists members', brunoMembers, 200, ['Alice', 'Bob', 'Carol']);
if (brunoMembers.status === 200 && brunoMembers.json.some((m) => m.project_id !== 2)) {
  failures.push('Bruno member list contains non-Beta accounts');
}

check('Alice reads Beta tasks', await call('GET', '/tasks?project_id=2', { token: alice }), 403, ['Beta secret']);
check('Alice edits Beta task 7', await call('PATCH', '/tasks/7', { token: alice, body: { title: 'Hijacked' } }), 403, ['Beta secret']);
check('Alice confirms Beta owner Bruno', await call('POST', '/members/4/confirm', { token: alice }), [400, 403]);
check('Alice grants admin to herself', await call('POST', '/members/2/role', { token: alice, body: { role: 'admin' } }), 403);

const aliceMembers = await call('GET', '/members', { token: alice });
check('Alice lists members', aliceMembers, 200, ['Bruno']);
if (aliceMembers.status === 200 && aliceMembers.json.some((m) => m.project_id !== 1)) {
  failures.push('Alice member list contains non-Alpha accounts');
}

check('Anonymous task read', await call('GET', '/tasks?project_id=1'), 401, alphaTitles);
check('Anonymous member read', await call('GET', '/members'), 401);

const integrity = await call('GET', '/tasks?project_id=1', { token: alice });
const task1 = integrity.json.find((t) => t.id === 1);
if (!task1 || task1.title !== 'Project kickoff' || task1.status !== 'todo') {
  failures.push(`Alpha task 1 was modified: ${JSON.stringify(task1)}`);
}
const beta = await call('GET', '/tasks?project_id=2', { token: bruno });
if (!beta.json.some((t) => t.title === 'Beta secret' && t.id === 7)) {
  failures.push('Beta task 7 missing after cross-project attempts');
}

if (failures.length) {
  console.error('\nE6 FAILURES:\n' + failures.join('\n'));
  process.exit(1);
}
console.log('\nE6 PASSED: cross-project access denied and no data leaked.');

