import { clickLabel, clickText, evaluate, pageText, send, shot, sleep, waitForText } from './lib.mjs';
import { clickAt } from './cdp2.mjs';

function assert(condition, message, text = '') {
  if (!condition) throw new Error(`${message}\n${text.slice(0, 1400)}`);
}

// 1) Server rejects an invalid bearer token without leaking data.
const bad = await fetch('http://localhost:8000/api/v1/members', {
  headers: { Authorization: 'Bearer invalid.token.value' },
});
const badBody = await bad.text();
console.log(`invalid token -> ${bad.status} ${badBody}`);
assert(bad.status === 401, `Invalid token expected 401, got ${bad.status}`);
assert(!/Alice|Bob|Carol|Bruno/.test(badBody), 'Invalid token response leaked members');

// 2) Browser back while logged in must not land on the login screen.
await evaluate(send, 'history.back()');
await sleep(2500);
let state = await evaluate(send, `({ url: location.href, text: document.body.innerText.slice(0, 200) })`);
console.log('after back (logged in):', state.url);
assert(state.url.includes('/home'), `Back while logged in left home: ${state.url}`);

// 3) Log out via the avatar menu.
const avatar = await evaluate(send, `(() => {
  for (const el of document.querySelectorAll('flt-semantics[flt-tappable]')) {
    const r = el.getBoundingClientRect();
    if (r.y < 60 && r.x > 950 && r.width > 20) return { x: r.x + r.width / 2, y: r.y + r.height / 2 };
  }
  return null;
})()`);
assert(avatar, 'Avatar not found');
await clickAt(send, avatar.x, avatar.y);
await sleep(1200);
await clickLabel('^Log out$');
await sleep(3000);
await waitForText('Log in', 20000);
state = await evaluate(send, `({ url: location.href })`);
console.log('after logout:', state.url);
assert(state.url.includes('/login'), `Logout did not route to login: ${state.url}`);
await shot('e8-logged-out');

// 4) Back after logout must stay on login, with no residual data.
await evaluate(send, 'history.back()');
await sleep(2500);
let text = await pageText();
state = await evaluate(send, `({ url: location.href })`);
console.log('after back (logged out):', state.url);
assert(state.url.includes('/login'), `Back after logout left login: ${state.url}`);
assert(/Log in/.test(text), 'Login form missing after back', text);
assert(!/Admin E2E|Beta secret|Project kickoff/.test(text), 'Residual data after logout', text);
await shot('e8-back-after-logout');

// 5) Reload after logout keeps the login screen and no data.
await send('Page.enable');
await send('Page.reload', { ignoreCache: false });
let placeholder = false;
for (let i = 0; i < 60; i += 1) {
  placeholder = await evaluate(send, `!!document.querySelector('flt-semantics-placeholder')`);
  if (placeholder) break;
  await sleep(500);
}
if (placeholder) await evaluate(send, `document.querySelector('flt-semantics-placeholder').click()`);
await sleep(1500);
await waitForText('Log in', 30000);
text = await pageText();
state = await evaluate(send, `({ url: location.href })`);
console.log('after reload:', state.url);
assert(state.url.includes('/login'), `Reload left login: ${state.url}`);
assert(!/Admin E2E|Beta secret|Project kickoff/.test(text), 'Residual data after reload', text);
await shot('e8-reload-login');

// 6) Direct /home URL without a session redirects to login.
await evaluate(send, `location.hash = '#/home'`);
await sleep(2500);
text = await pageText();
state = await evaluate(send, `({ url: location.href })`);
console.log('direct /home:', state.url);
assert(state.url.includes('/login'), `Direct /home not redirected: ${state.url}`);
assert(/Log in/.test(text), 'Login form missing after direct /home', text);
assert(!/Admin E2E|Beta secret|Project kickoff/.test(text), 'Residual data after direct /home', text);
await shot('e8-direct-home-blocked');

console.log('E8 UI part 1 PASSED: logout, back, reload and direct URL all land on login.');
process.exit(0);

