import { clickLabel, clickText, evaluate, fill, pageText, send, shot, sleep, waitForText } from './lib.mjs';
import { clickAt } from './cdp2.mjs';

function assert(condition, message, detail = '') {
  if (!condition) throw new Error(`${message} ${detail}`);
}

async function storage() {
  return evaluate(send, `Object.fromEntries(Object.entries(localStorage))`);
}

async function sampleLum(x = 800, y = 560) {
  const { data } = await send('Page.captureScreenshot', { format: 'png', captureBeyondViewport: false });
  return evaluate(send, `(async () => {
    const img = new Image();
    img.src = 'data:image/png;base64,${data}';
    await img.decode();
    const c = document.createElement('canvas');
    c.width = img.width; c.height = img.height;
    const ctx = c.getContext('2d');
    ctx.drawImage(img, 0, 0);
    const p = ctx.getImageData(${x}, ${y}, 1, 1).data;
    return { r: p[0], g: p[1], b: p[2], lum: Math.round(0.2126 * p[0] + 0.7152 * p[1] + 0.0722 * p[2]) };
  })()`);
}

async function reloadToLogin() {
  await send('Page.enable');
  await send('Page.reload', { ignoreCache: false });
  let placeholder = false;
  for (let i = 0; i < 80; i += 1) {
    placeholder = await evaluate(send, `!!document.querySelector('flt-semantics-placeholder')`);
    if (placeholder) break;
    await sleep(500);
  }
  if (placeholder) await evaluate(send, `document.querySelector('flt-semantics-placeholder').click()`);
  await sleep(1500);
  await waitForText('Log in', 30000);
}

async function logout() {
  const avatar = await evaluate(send, `(() => {
    for (const el of document.querySelectorAll('flt-semantics[flt-tappable]')) {
      const r = el.getBoundingClientRect();
      if (r.y < 60 && r.x > 950 && r.width > 20) return { x: r.x + r.width / 2, y: r.y + r.height / 2 };
    }
    return null;
  })()`);
  if (!avatar) throw new Error('Avatar not found');
  await clickAt(send, avatar.x, avatar.y);
  await sleep(1000);
  await clickLabel('^Log out$');
  await sleep(3000);
  await waitForText('Log in', 20000);
}

async function loginAdmin() {
  await fill('Email', 'admin@e2e.test');
  await fill('Password', 'Passw0rd!23');
  await clickText('^Log in$');
  await sleep(4000);
  await waitForText('Projects', 30000);
}

async function chooseTheme(mode) {
  await clickText('^Theme$');
  await sleep(1000);
  await clickLabel(`^${mode}$`);
  await sleep(2000);
}

// --- Light mode on the main screens ---
let lum = await sampleLum();
assert(lum.lum > 200, 'Projects is not light', JSON.stringify(lum));
await shot('e9-light-projects-verified');

await clickLabel('^Members$');
await sleep(2500);
await waitForText('Add user', 20000);
lum = await sampleLum();
assert(lum.lum > 200, 'Members is not light', JSON.stringify(lum));
await shot('e9-light-members');

await clickLabel('^Tasks$');
await sleep(3000);
await waitForText('Project kickoff', 20000);
lum = await sampleLum();
assert(lum.lum > 200, 'Tasks is not light', JSON.stringify(lum));
await shot('e9-light-tasks');

// --- Light survives logout and reload ---
await logout();
lum = await sampleLum();
assert(lum.lum > 200, 'Login is not light', JSON.stringify(lum));
await shot('e9-light-login');

await reloadToLogin();
let store = await storage();
assert(store['flutter.themeMode'] === '"light"', 'Light preference not persisted', JSON.stringify(store));
lum = await sampleLum();
assert(lum.lum > 200, 'Login is not light after reload', JSON.stringify(lum));
await shot('e9-light-reload');

// --- Dark mode on the main screens ---
await loginAdmin();
await chooseTheme('Dark');
store = await storage();
assert(store['flutter.themeMode'] === '"dark"', 'Dark preference not stored', JSON.stringify(store));
lum = await sampleLum();
assert(lum.lum < 70, 'Projects is not dark', JSON.stringify(lum));
await shot('e9-dark-projects-verified');

await clickLabel('^Members$');
await sleep(2500);
await waitForText('Add user', 20000);
lum = await sampleLum();
assert(lum.lum < 70, 'Members is not dark', JSON.stringify(lum));
await shot('e9-dark-members');

await clickLabel('^Tasks$');
await sleep(3000);
await waitForText('Project kickoff', 20000);
lum = await sampleLum();
assert(lum.lum < 70, 'Tasks is not dark', JSON.stringify(lum));
await shot('e9-dark-tasks');

await clickText('^Theme$');
await sleep(1000);
await shot('e9-dark-dialog');
await send('Input.dispatchKeyEvent', { type: 'keyDown', key: 'Escape', code: 'Escape', windowsVirtualKeyCode: 27 });
await send('Input.dispatchKeyEvent', { type: 'keyUp', key: 'Escape', code: 'Escape', windowsVirtualKeyCode: 27 });
await sleep(1000);

// --- Dark survives reload (session intentionally not persisted) ---
await reloadToLogin();
store = await storage();
assert(store['flutter.themeMode'] === '"dark"', 'Dark preference not persisted', JSON.stringify(store));
lum = await sampleLum();
assert(lum.lum < 70, 'Login is not dark after reload', JSON.stringify(lum));
await shot('e9-dark-reload');

// --- System mode follows the OS/browser preference ---
await loginAdmin();
await chooseTheme('System');
store = await storage();
assert(store['flutter.themeMode'] === '"system"', 'System preference not stored', JSON.stringify(store));

await send('Emulation.setEmulatedMedia', {
  features: [{ name: 'prefers-color-scheme', value: 'dark' }],
});
await sleep(2000);
lum = await sampleLum();
assert(lum.lum < 70, 'System did not follow dark preference', JSON.stringify(lum));
await shot('e9-system-dark');

await send('Emulation.setEmulatedMedia', {
  features: [{ name: 'prefers-color-scheme', value: 'light' }],
});
await sleep(2000);
lum = await sampleLum();
assert(lum.lum > 200, 'System did not follow light preference', JSON.stringify(lum));
await shot('e9-system-light');

// --- System choice itself persists across restart ---
await send('Emulation.setEmulatedMedia', { features: [] });
await sleep(1500);
await reloadToLogin();
store = await storage();
assert(store['flutter.themeMode'] === '"system"', 'System preference not persisted', JSON.stringify(store));
lum = await sampleLum();
assert(lum.lum > 200, 'System default is not light in this browser', JSON.stringify(lum));
await shot('e9-system-reload');

console.log('E9 PASSED: light, dark and system render correctly and persist.');
process.exit(0);

import { evaluate, pageText, send, shot, sleep } from './lib.mjs';

const env = await evaluate(send, `({
  url: location.href,
  storage: Object.fromEntries(Object.entries(localStorage)),
  prefersDark: matchMedia('(prefers-color-scheme: dark)').matches,
