import { clickAt, connect, evaluate, screenshot, sleep } from './cdp.mjs';
import { clickLabel, clickText, login, pageText, shot, waitForText } from './lib.mjs';

const API = 'http://localhost:8000/api/v1';
const { send } = await connect();

function assert(condition, message, detail = '') {
  if (!condition) throw new Error(`${message}\n${String(detail).slice(0, 1600)}`);
}

async function apiToken(email) {
  const response = await fetch(`${API}/auth/login`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ email, password: 'Passw0rd!23' }),
  });
  if (response.status !== 200) throw new Error(`${email} API login ${response.status}`);
  return (await response.json()).access_token;
}

const adminToken = await apiToken('admin@e2e.test');
async function members() {
  const response = await fetch(`${API}/members`, {
    headers: { Authorization: `Bearer ${adminToken}` },
  });
  return response.json();
}
async function roleOf(id) {
  return (await members()).find((m) => m.id === id)?.role;
}

async function reload() {
  await send('Page.enable');
  await send('Page.reload', { ignoreCache: false });
  let placeholder = false;
  for (let i = 0; i < 80; i += 1) {
    placeholder = await evaluate(send, `!!document.querySelector('flt-semantics-placeholder')`);
    if (placeholder) break;
    await sleep(500);
  }
  if (placeholder) await evaluate(send, `document.querySelector('flt-semantics-placeholder').click()`);
  await sleep(1500);
  await waitForText('Log in', 30000);
}

async function logout() {
  const avatar = await evaluate(send, `(() => {
    for (const el of document.querySelectorAll('flt-semantics[flt-tappable]')) {
      const r = el.getBoundingClientRect();
      if (r.y < 60 && r.x > 950 && r.width > 20) return { x: r.x + r.width / 2, y: r.y + r.height / 2 };
    }
    return null;
  })()`);
  assert(avatar, 'Avatar not found');
  await clickAt(send, avatar.x, avatar.y);
  await sleep(1200);
  await clickLabel('^Log out$');
  await sleep(3000);
  await waitForText('Log in', 20000);
}

async function memberRow(name) {
  const rect = await evaluate(send, `(() => {
    for (const el of document.querySelectorAll('flt-semantics')) {
      if (el.textContent.trim() !== ${JSON.stringify(name)}) continue;
      const r = el.getBoundingClientRect();
      if (r.width && r.height) return { x: r.x, y: r.y, w: r.width, h: r.height };
    }
    return null;
  })()`);
  assert(rect, `Member row not found: ${name}`);
  return rect;
}

async function openMembers() {
  await clickLabel('^Members$');
  await sleep(3000);
  await waitForText('Carol', 20000);
}

async function changeRole(name, role) {
  const row = await memberRow(name);
  await clickLabel('^Change role$', { within: [0, row.y, 1018, row.h] });
  await sleep(800);
  await clickLabel(`^${role}$`);
  await sleep(800);
}

async function waitApiRole(id, expected) {
  for (let i = 0; i < 50; i += 1) {
    if ((await roleOf(id)) === expected) return;
    await sleep(300);
  }
  throw new Error(`Role of ${id} never became ${expected} (still ${await roleOf(id)})`);
}

// --- Start from a clean login page with the rebuilt app ---
await reload();
await login('admin@e2e.test', 'Passw0rd!23');
await waitForText('Projects', 30000);
await openMembers();

let text = await pageText();
assert(/Alice/.test(text) && /Bob/.test(text) && /Bruno/.test(text), 'Roster incomplete', text);
assert((await roleOf(3)) === 'user', 'Bob should start as user');

// --- Promote Bob: menu, confirmation, API + UI ---
await changeRole('Bob', 'Admin');
await waitForText('Give admin access', 10000);
await shot('e5-confirm-admin');
await clickLabel('^Make admin$');
await waitApiRole(3, 'admin');
await sleep(2000);
text = await pageText();
