import { clickLabel, clickText, evaluate, fill, pageText, shot, sleep, waitForText } from './lib.mjs';

function assert(condition, message, text = '') {
  if (!condition) throw new Error(`${message}\n${String(text).slice(0, 1400)}`);
}

// Precondition: an admin session is open and the API was restarted with a
// different SECRET_KEY, so the in-memory token is now rejected with 401.
const before = await pageText();
assert(/Bob/.test(before), 'Expected the Members tab of an open admin session', before);
const urlBefore = await evaluate(send => send, `location.href`).catch(() => null);
console.log('start url:', urlBefore);

// Any authenticated request triggers the 401 handler; the Tasks tab issues one.
await clickLabel('^Tasks$');
await waitForText('Your session expired', 20000);
await sleep(2000);

let text = await pageText();
const state = await evaluate(send => send, `({ url: location.href, token: null })`).catch(() => null);
console.log('after 401 url:', state?.url);

assert(state.url.includes('/login'), `Expected /login after 401, got ${state.url}`);
assert(/Your session expired\. Log in again\./.test(text), 'Expiry notice missing', text);
assert(/Log in/.test(text), 'Login form missing', text);
assert(!/Admin E2E|Bob|Alice|Bruno|Carol|Alpha|Beta/.test(text), 'Session data still rendered after 401', text);
await shot('e8c-expired-login');

// A rejected login must not re-trigger the expiry path: wrong password shows
// only the normal credential error and clears the notice.
await fill('Email', 'admin@e2e.test');
await fill('Password', 'not-the-password');
await clickText('^Log in$');
await sleep(2500);
text = await pageText();
assert(/Wrong email or password\./.test(text), 'Credential error missing', text);
assert(!/Your session expired/.test(text), 'Login 401 re-triggered the expiry notice', text);
await shot('e8c-wrong-password');

console.log('E8 PASSED: a 401 on an authenticated request cleared the session, showed the notice and no data.');
process.exit(0);

