// --- Pagination state ---

class PaginatedList<T> {
  const PaginatedList({
    required this.items,
    this.page = 1,
    this.pageSize = 20,
    this.hasMore = true,
    this.isLoading = false,
    this.isLoadingMore = false,
    this.error,
  });

  final List<T> items;
  final int page;
  final int pageSize;
  final bool hasMore;
  final bool isLoading;
  final bool isLoadingMore;
  final Object? error;

  PaginatedList<T> copyWith({
    List<T>? items,
    int? page,
    int? pageSize,
    bool? hasMore,
    bool? isLoading,
    bool? isLoadingMore,
    Object? error,
  }) {
    return PaginatedList<T>(
      items: items ?? this.items,
      page: page ?? this.page,
      pageSize: pageSize ?? this.pageSize,
      hasMore: hasMore ?? this.hasMore,
      isLoading: isLoading ?? this.isLoading,
      isLoadingMore: isLoadingMore ?? this.isLoadingMore,
      error: error ?? this.error,
    );
  }

  PaginatedList<T> get firstPageLoading => copyWith(page: 1, isLoading: true, error: null);

  PaginatedList<T> get loadingMore => copyWith(isLoadingMore: true, error: null);
}

// --- Providers (StreamProvider based) ---

final projectServiceProvider = Provider<ProjectService>(
  (ref) => ProjectService(ref.watch(apiClientProvider)),
);

final taskServiceProvider = Provider<TaskService>(
  (ref) => TaskService(ref.watch(apiClientProvider)),
);

final memberServiceProvider = Provider<MemberService>(
  (ref) => MemberService(ref.watch(apiClientProvider)),
);

final authServiceProvider = Provider<AuthService>(
  (ref) => AuthService(ref.watch(apiClientProvider)),
);

/// All projects, paginated. Pulled fresh on every DataSync ping and on
/// [ref.invalidate] (pull-to-refresh).
final projectListProvider = StreamProvider<PaginatedList<Project>>((ref) {
  final service = ref.watch(projectServiceProvider);
  return service.watchProjects().map((list) => PaginatedList<Project>(
    items: list.items,
    page: (list.offset ~/ list.limit) + 1,
    pageSize: list.limit,
    hasMore: list.hasMore,
  ));
});

/// Tasks of one project, paginated. Family key is [projectId].
final projectTasksProvider = StreamProvider.family<PaginatedList<Task>, int>(
  (ref, projectId) {
    final service = ref.watch(taskServiceProvider);
    return service.watchProjectTasks(projectId).map((list) => PaginatedList<Task>(
      items: list.items,
      page: (list.offset ~/ list.limit) + 1,
      pageSize: list.limit,
      hasMore: list.hasMore,
    ));
  },
);

/// Tasks assigned to one person, paginated. Family key is [assigneeId].
final myTasksProvider = StreamProvider.family<PaginatedList<Task>, int>(
  (ref, assigneeId) {
    final service = ref.watch(taskServiceProvider);
    return service.watchTasksAssignedTo(assigneeId).map((list) => PaginatedList<Task>(
      items: list.items,
      page: (list.offset ~/ list.limit) + 1,
      pageSize: list.limit,
      hasMore: list.hasMore,
    ));
  },
);

/// Members visible to the caller, paginated.
final visibleMembersProvider = StreamProvider<PaginatedList<Account>>((ref) {
  final service = ref.watch(memberServiceProvider);
  return service.watchVisibleMembers().map((list) => PaginatedList<Account>(
    items: list.items,
    page: (list.offset ~/ list.limit) + 1,
    pageSize: list.limit,
    hasMore: list.hasMore,
  ));
});

/// Notification service.
final notificationServiceProvider = Provider<NotificationService>(
  (ref) => NotificationService(ref.watch(apiClientProvider)),
);

/// First page of the caller's notifications.
final notificationListProvider = FutureProvider<NotificationList>((ref) async {
  final service = ref.watch(notificationServiceProvider);
  return service.list(limit: 20, offset: 0);
});

/// First page of unread notifications.
final unreadNotificationListProvider = FutureProvider<NotificationList>((ref) async {
  final service = ref.watch(notificationServiceProvider);
  return service.list(limit: 20, offset: 0, unreadOnly: true);
});

/// Analytics service.
final analyticsServiceProvider = Provider<AnalyticsService>(
  (ref) => AnalyticsService(ref.watch(apiClientProvider)),
);

/// Subtask service.
final subtaskServiceProvider = Provider<SubtaskService>(
  (ref) => SubtaskService(ref.watch(apiClientProvider)),
);

/// Dashboard stats for one project. Family key is [projectId].
final dashboardStatsProvider = FutureProvider.family<DashboardStats, int>(
  (ref, projectId) async {
    final service = ref.watch(analyticsServiceProvider);
    return service.getDashboard(projectId);
  },
);

