/// Base URL of the FastAPI backend (all feature routes live under `/api/v1`).
///
/// Override per platform/build, e.g. for an Android emulator:
/// `flutter run --dart-define=API_BASE_URL=http://10.0.2.2:8000/api/v1`
const _apiBaseUrl = String.fromEnvironment(
  'API_BASE_URL',
  defaultValue: 'http://localhost:8000/api/v1',
);

/// Key used to persist the JWT token in shared preferences.
const _sessionTokenKey = 'session_token';

void main() {
  WidgetsFlutterBinding.ensureInitialized();

  final apiClient = HttpApiClient(_apiBaseUrl);

  // Restore the persisted JWT token (if any) so the session survives app
  // restarts. The router's redirect logic then decides whether to show the
  // splash  home flow or send the user to the login screen.
  SharedPreferences.getInstance().then((prefs) {
    final token = prefs.getString(_sessionTokenKey);
    if (token != null && token.isNotEmpty) {
      apiClient.setToken(token);
    }
  });

  runApp(
    ProviderScope(
      overrides: [
        apiClientProvider.overrideWithValue(apiClient),
      ],
      child: const TaskPlannerApp(),
    ),
  );
}
import 'dart:async';
import 'dart:convert';

import 'package:http/http.dart' as http;

/// HTTP access to the FastAPI backend.
///
/// Errors are normalized to the shapes the screens already handle:
///  * [StateError] for HTTP error details, server validation failures,
///    unreachable-server problems, and timeouts;
///  * [ArgumentError] when the server reports a `project_required` or
///    `invalid_assignment` code (assignment / project-choice violations).
abstract class ApiClient {
  String get baseUrl;

  /// Bearer token attached to every request after a successful login.
  void setToken(String token);

  void clearToken();

  /// Called once when an authenticated request is rejected with 401, so the
  /// session layer can end the session and return to the login screen.
  /// Requests without a token (login, sign-up) never trigger it.
  void setUnauthorizedHandler(void Function()? handler);

  Future<dynamic> get(String path);

  Future<dynamic> post(String path, [Map<String, dynamic>? body]);

  Future<dynamic> patch(String path, [Map<String, dynamic>? body]);

  Future<dynamic> delete(String path);
}

/// [ApiClient] built on `package:http`. Tests inject a fake client instead.
class HttpApiClient implements ApiClient {
  HttpApiClient(
    this.baseUrl, {
    http.Client? httpClient,
    this.timeout = const Duration(seconds: 15),
  }) : _http = httpClient ?? http.Client();

  static const _offlineMessage =
      'Could not reach the server. Check that the API is running.';

  @override
  final String baseUrl;

  /// Per-request timeout; longer than that is reported as offline.
  final Duration timeout;
  final http.Client _http;
  String? _token;
  void Function()? _onUnauthorized;

  /// Current bearer token (null when logged out). Exposed for tests/state UI.
  String? get token => _token;

  @override
  void setToken(String token) => _token = token;

  @override
  void clearToken() => _token = null;

  @override
  void setUnauthorizedHandler(void Function()? handler) =>
      _onUnauthorized = handler;

  @override
  Future<dynamic> get(String path) => _request('GET', path);

  @override
  Future<dynamic> post(String path, [Map<String, dynamic>? body]) =>
      _request('POST', path, body: body);

  @override
  Future<dynamic> patch(String path, [Map<String, dynamic>? body]) =>
      _request('PATCH', path, body: body);

  @override
  Future<dynamic> delete(String path) => _request('DELETE', path);

  Future<dynamic> _request(
    String method,
    String path, {
    Map<String, dynamic>? body,
  }) async {
    final uri = Uri.parse('$baseUrl$path');
    final hadToken = _token != null;
    final headers = <String, String>{
      'Content-Type': 'application/json',
      if (_token != null) 'Authorization': 'Bearer $_token',
    };
    final encoded = body == null ? null : jsonEncode(body);

    http.Response response;
    try {
      final request = switch (method) {
        'GET' => _http.get(uri, headers: headers),
        'POST' => _http.post(uri, headers: headers, body: encoded),
        'PATCH' => _http.patch(uri, headers: headers, body: encoded),
        'DELETE' => _http.delete(uri, headers: headers),
        _ => throw UnsupportedError('HTTP $method is not supported.'),
      };
      response = await request.timeout(timeout);
    } on UnsupportedError {
      rethrow;
    } on TimeoutException {
      throw StateError(_offlineMessage);
    } catch (_) {
      throw StateError(_offlineMessage);
    }
    return _decode(response, hadToken: hadToken);
  }

  dynamic _decode(http.Response response, {required bool hadToken}) {
    if (response.statusCode == 401 && hadToken) {
      _onUnauthorized?.call();
    }
    dynamic decoded;
    if (response.body.isNotEmpty) {
      try {
        decoded = jsonDecode(response.body);
      } catch (_) {
        throw StateError('The server sent an unreadable response.');
      }
    }
    if (response.statusCode >= 200 && response.statusCode < 300) {
      return decoded;
    }

    final detail = decoded is Map ? decoded['detail'] : null;
    String message;
    String? code;
    if (detail is Map) {
      message = detail['message']?.toString() ?? 'Request failed.';
      code = detail['code']?.toString();
    } else {
      message =
          detail?.toString() ?? 'Request failed (HTTP ${response.statusCode}).';
    }
    if (code == 'invalid_assignment' || code == 'project_required') {
      throw ArgumentError(message);
    }
    throw StateError(message);
  }
}

