const _apiBaseUrl = String.fromEnvironment(
  'API_BASE_URL',
  defaultValue: 'http://localhost:8000/api/v1',
);

/// Key used to persist the JWT token in shared preferences.
const _sessionTokenKey = 'session_token';

void main() {
  WidgetsFlutterBinding.ensureInitialized();

  final apiClient = HttpApiClient(_apiBaseUrl);

  // Restore the persisted JWT token (if any) so the session survives app
  // restarts. The router's redirect logic then decides whether to show the
  // splash  home flow or send the user to the login screen.
  SharedPreferences.getInstance().then((prefs) {
    final token = prefs.getString(_sessionTokenKey);
    if (token != null && token.isNotEmpty) {
      apiClient.setToken(token);
    }
  });

  runApp(
    ProviderScope(
      overrides: [
        apiClientProvider.overrideWithValue(apiClient),
      ],
      child: const TaskPlannerApp(),
    ),
  );
}
