import 'package:flutter_test/flutter_test.dart';
import 'package:task_planner/core/rules.dart';

void main() {
  group('task assignment', () {
    test('project-level assignment needs no person', () {
      validateTaskAssignment(
        taskProjectId: 1,
        assigneeId: null,
        assigneeProjectId: null,
      );
    });

    test('person from the same project is accepted', () {
      validateTaskAssignment(
        taskProjectId: 1,
        assigneeId: 7,
        assigneeProjectId: 1,
      );
    });

    test('person from another project is rejected', () {
      expect(
        () => validateTaskAssignment(
          taskProjectId: 1,
          assigneeId: 7,
          assigneeProjectId: 2,
        ),
        throwsArgumentError,
      );
    });
  });

  group('login gate', () {
    test('active accounts can log in', () {
      expect(canLogIn(MemberStatus.active), isTrue);
    });

    test('pending accounts cannot log in', () {
      expect(canLogIn(MemberStatus.pending), isFalse);
    });
  });

  group('roles', () {
    test('admin sees all five tabs in order', () {
      expect(visibleTabs(Roles.admin), ['projects', 'members', 'tasks', 'planner', 'dashboard']);
    });

    test('owner and user see members, tasks, mine, planner, and dashboard', () {
      expect(visibleTabs(Roles.projectOwner), ['members', 'tasks', 'mine', 'planner', 'dashboard']);
      expect(visibleTabs(Roles.user), ['members', 'tasks', 'mine', 'planner', 'dashboard']);
    });

    test('requireAdmin rejects non-admins', () {
      expect(() => requireAdmin(Roles.user), throwsStateError);
      expect(() => requireAdmin(Roles.projectOwner), throwsStateError);
      requireAdmin(Roles.admin);
    });

    test('requireOwnerOrAdmin rejects plain users', () {
      expect(() => requireOwnerOrAdmin(Roles.user), throwsStateError);
      requireOwnerOrAdmin(Roles.projectOwner);
      requireOwnerOrAdmin(Roles.admin);
    });
  });

  group('planner classifiers', () {
    final now = DateTime(2026, 10, 12, 15, 30);

    test('overdue is incomplete with a past due date', () {
      expect(
        isOverdue(
          status: TaskStatus.todo,
          dueDate: DateTime(2026, 10, 11, 23, 59),
          now: now,
        ),
        isTrue,
      );
    });

    test('completed tasks never match today/upcoming/overdue', () {
      const status = TaskStatus.completed;
      expect(
        isOverdue(status: status, dueDate: DateTime(2026, 10, 11), now: now),
        isFalse,
      );
      expect(
        isDueToday(status: status, dueDate: DateTime(2026, 10, 12), now: now),
        isFalse,
      );
      expect(
        isUpcoming(status: status, dueDate: DateTime(2026, 10, 13), now: now),
        isFalse,
      );
    });

    test('today matches the calendar day regardless of time', () {
      expect(
        isDueToday(
          status: TaskStatus.todo,
          dueDate: DateTime(2026, 10, 12, 0, 0),
          now: now,
        ),
        isTrue,
      );
      expect(
        isDueToday(
          status: TaskStatus.todo,
          dueDate: DateTime(2026, 10, 13),
          now: now,
        ),
        isFalse,
      );
    });

    test('upcoming is incomplete with a future due date', () {
      expect(
        isUpcoming(
          status: TaskStatus.todo,
          dueDate: DateTime(2026, 10, 13),
          now: now,
        ),
        isTrue,
      );
      expect(
        isUpcoming(
          status: TaskStatus.todo,
          dueDate: DateTime(2026, 10, 12),
          now: now,
        ),
        isFalse,
      );
    });

    test('tasks without a due date match nothing', () {
      expect(
        isOverdue(status: TaskStatus.todo, dueDate: null, now: now),
        isFalse,
      );
      expect(
        isDueToday(status: TaskStatus.todo, dueDate: null, now: now),
        isFalse,
      );
      expect(
        isUpcoming(status: TaskStatus.todo, dueDate: null, now: now),
        isFalse,
      );
    });
  });
}

"""Business rules - server-side port of task_planner/lib/core/rules.dart.

The server is the enforcer; the Dart copy stays as a UX-side check only.
"""
from .errors import AssignmentError, ForbiddenError, RuleError

# Roles (cumulative: admin > project owner > user > viewer).
ADMIN = "admin"
PROJECT_OWNER = "project_owner"
TEAM_LEAD = "team_lead"
USER = "user"
VIEWER = "viewer"
ROLES = (ADMIN, PROJECT_OWNER, TEAM_LEAD, USER, VIEWER)

# Membership states.
PENDING = "pending"
ACTIVE = "active"

# Task states and priorities.
TASK_TODO = "todo"
TASK_COMPLETED = "completed"
PRIORITIES = ("low", "medium", "high")


def can_log_in(status: str) -> bool:
    """Only active accounts may log in; pending accounts await approval."""
    return status == ACTIVE


def is_admin(role: str) -> bool:
    return role == ADMIN


def is_owner_or_admin(role: str) -> bool:
    return role in (ADMIN, PROJECT_OWNER)


def is_viewer(role: str) -> bool:
    return role == VIEWER


def is_team_lead(role: str) -> bool:
    return role == TEAM_LEAD


def require_can_mutate(role: str) -> None:
    """Viewers cannot make any mutations (read-only)."""
    if is_viewer(role):
        raise ForbiddenError("Viewers cannot make changes.")


def require_admin(role: str) -> None:
    if not is_admin(role):
        raise ForbiddenError("Only an admin can do this.")


def require_owner_or_admin(role: str) -> None:
    if not is_owner_or_admin(role):
        raise ForbiddenError("Only a project owner or admin can do this.")


def validate_task_assignment(
    task_project_id: int, assignee_id: int | None, assignee_project_id: int | None
) -> None:
    """A task is assigned to its project (None) or one same-project person."""
    if assignee_id is not None and assignee_project_id != task_project_id:
        raise AssignmentError("Assignee must belong to the task project.")


def require_project_access(
    role: str, actor_project_id: int | None, project_id: int
) -> None:
    """Admins manage any project; everyone else only their own."""
    if not is_admin(role) and actor_project_id != project_id:
        raise ForbiddenError("You can only manage your own project tasks.")

