abstract class PaginatedNotifier<T> extends AutoDisposeAsyncNotifier<PaginatedList<T>> {
  int _page = 1;
  List<T> _items = [];
  bool _hasMore = true;
  bool _loadingMore = false;

  Future<PaginatedList<T>> fetchPage(int page);
  int idOf(T item);

  @override
  Future<PaginatedList<T>> build() async {
    _page = 1;
    _items = [];
    final result = await fetchPage(1);
    _items = result.items;
    _hasMore = result.hasMore;
    return result.copyWith(items: List.of(_items), page: 1, hasMore: _hasMore);
  }

  Future<void> loadMore() async {
    if (_loadingMore || !_hasMore) return;
    final current = state.valueOrNull;
    if (current == null) return;
    _loadingMore = true;
    state = AsyncData(current.copyWith(isLoadingMore: true, error: null));
    try {
      final next = await fetchPage(_page + 1);
      _page++;
      final seen = _items.map(idOf).toSet();
      _items = [..._items, ...next.items.where((e) => !seen.contains(idOf(e)))];
      _hasMore = next.hasMore;
      state = AsyncData(current.copyWith(
        items: List.of(_items), page: _page, hasMore: _hasMore, isLoadingMore: false));
    } catch (e) {
      state = AsyncData(current.copyWith(isLoadingMore: false, error: e));
    } finally {
      _loadingMore = false;
    }
  }

  Future<void> refresh() async {
    state = const AsyncLoading();
    state = await AsyncValue.guard(() async { ... });
  }
}
