18: /// Scoped roster. Owners and admins see pending/active statuses and the
19: /// pending-requests section; plain users see names only.
20: class MembersTab extends ConsumerStatefulWidget {
21:   const MembersTab({super.key});
22: 
23:   @override
24:   ConsumerState<MembersTab> createState() => _MembersTabState();
25: }
26: 
27: class _MembersTabState extends ConsumerState<MembersTab> {
28:   String _query = '';
29:   final _scrollController = ScrollController();
30: 
31:   @override
32:   void initState() {
33:     super.initState();
34:     _scrollController.addListener(_onScroll);
35:   }
36: 
37:   @override
38:   void dispose() {
39:     _scrollController.dispose();
40:     super.dispose();
41:   }
42: 
43:   void _onScroll() {
44:     if (_scrollController.position.pixels >=
45:             _scrollController.position.maxScrollExtent - 200 &&
46:         !_isLoadingMore) {
47:       _loadMore();
48:     }
49:   }
50: 
51:   bool get _isLoadingMore {
52:     final state = ref.read(visibleMembersProvider);
53:     return state.hasValue && state.value!.isLoadingMore;
54:   }
55: 
56:   Future<void> _loadMore() async {
57:     ref.invalidate(visibleMembersProvider);
58:   }
59: 
60:   Future<void> _refresh() async {
61:     ref.invalidate(visibleMembersProvider);
62:   }
63: 
64:   @override
65:   Widget build(BuildContext context) {
66:     final account = ref.watch(currentUserProvider);
67:     return account.when(
68:       loading: () => const Center(child: CircularProgressIndicator()),
69:       error: (e, _) => ErrorState(
70:         message: 'Could not load account: $e',
71:         onRetry: () => ref.invalidate(currentUserProvider),
72:       ),
73:       data: (user) {
74:         if (user == null) {
75:           return const Center(child: Text('Logged out.'));
76:         }
77:         final canManage = isOwnerOrAdmin(user.role);
78:         final membersState = ref.watch(visibleMembersProvider);
79:         return Scaffold(
80:           backgroundColor: Colors.transparent,
81:           floatingActionButton: canManage
82:               ? FloatingActionButton(
83:                   tooltip: 'Add user',
84:                   onPressed: () => _addDialog(context, ref, user),
85:                   child: const Icon(Icons.person_add),
86:                 )
87:               : null,
88:           body: membersState.when(
89:             loading: () => const Center(child: CircularProgressIndicator()),
90:             error: (e, _) => ErrorState(
91:               message: 'Could not load members: $e',
92:               onRetry: _refresh,
93:             ),
94:             data: (paginated) => _body(context, ref, user, paginated, canManage),
95:           ),
96:         );
97:       },
98:     );
99:   }
100: 
101:   Widget _body(
102:     BuildContext context,
103:     WidgetRef ref,
104:     Account user,
105:     PaginatedList<Account> paginated,
106:     bool canManage,
107:   ) {
108:     final list = paginated.items;
109:     final searched = _query.isEmpty
110:         ? list
111:         : list
112:               .where(
113:                 (m) =>
114:                     m.name.toLowerCase().contains(_query) ||
115:                     m.email.toLowerCase().contains(_query) ||
116:                     (m.position?.toLowerCase().contains(_query) ?? false),
117:               )
118:               .toList();
119:     final pending = searched
120:         .where((m) => m.status == MemberStatus.pending)
121:         .toList();
122:     final active = searched
123:         .where((m) => m.status != MemberStatus.pending)
124:         .toList();
125:     final isEmpty = list.isEmpty;
126:     final noMatches = !isEmpty && searched.isEmpty;
127: 
128:     return Column(
129:       children: [
130:         Padding(
131:           padding: const EdgeInsets.fromLTRB(12, 10, 12, 2),
132:           child: DebouncedSearchField(
133:             hintText: 'Search members',
134:             onChanged: (query) => setState(() => _query = query),
135:           ),
136:         ),
137:         Expanded(
138:           child: NotificationListener<ScrollNotification>(
139:             onNotification: (notification) {
140:               if (notification is ScrollEndNotification &&
141:                   notification.metrics.pixels >=
142:                       notification.metrics.maxScrollExtent - 200 &&
143:                   !paginated.isLoadingMore &&
144:                   paginated.hasMore) {
145:                 _loadMore();
146:               }
147:               return false;
148:             },
149:             child: RefreshIndicator(
150:               onRefresh: _refresh,
151:               child: noMatches
152:                   ? const EmptyState(
153:                       scrollable: true,
154:                       icon: Icons.search_off,
155:                       title: 'No matches',
156:                       hint: 'Try a different search',
157:                     )
158:                   : isEmpty
159:                   ? EmptyState(
160:                       scrollable: true,
161:                       icon: Icons.people_outline,
162:                       title: 'No members yet',
163:                       hint: canManage ? 'Tap + to add one' : null,
164:                     )
165:                   : ListView(
166:                       controller: _scrollController,
167:                       physics: const AlwaysScrollableScrollPhysics(),
168:                       padding: const EdgeInsets.fromLTRB(12, 8, 12, 88),
169:                       children: [
170:                         // Pending members are shown by name to everyone;
171:                         // only owners/admins get the confirmation section
172:                         // and status chips.
173:                         if (canManage && pending.isNotEmpty) ...[
174:                           const SectionHeader('Waiting for confirmation'),
175:                           for (final m in pending) ...[
176:                             _card(context, ref, user, m, pending: true),
177:                             const SizedBox(height: 8),
178:                           ],
179:                         ],
180:                         if (canManage) ...[
181:                           if (active.isNotEmpty) ...[
182:                             const SectionHeader('Members'),
183:                             for (final m in active) ...[
184:                               _card(context, ref, user, m, pending: false),
185:                               const SizedBox(height: 8),
186:                             ],
187:                           ],
188:                         ] else if (searched.isNotEmpty) ...[
189:                           const SectionHeader('Members'),
190:                           for (final m in searched) ...[
191:                             _card(context, ref, user, m, pending: false),
192:                             const SizedBox(height: 8),
193:                           ],
194:                         ],
195:                         if (paginated.hasMore)
196:                           const Padding(
197:                             padding: EdgeInsets.all(16),
198:                             child: Center(child: CircularProgressIndicator()),
199:                           ),
200:                       ],
201:                     ),
202:             ),
203:           ),
204:         ),
205:       ],
206:     );
207:   }
208: 
209:   Widget _card(
210:     BuildContext context,
211:     WidgetRef ref,
212:     Account viewer,
213:     Account member, {
214:     required bool pending,
215:   }) {
216:     // Status is owner/admin information (access-control skill); plain users
217:     // see names only.
218:     final canConfirm =
219:         pending &&
220:         (isAdmin(viewer.role) ||
221:             (viewer.role == Roles.projectOwner &&
222:                 member.projectId == viewer.projectId));
223:     // Role management is admin-only. A project owner's role is bound to the
224:     // project by Assign owner, and changing one's own role could lock the
225:     // admin out, so neither is offered here.
226:     final canChangeRole =
227:         isAdmin(viewer.role) &&
228:         member.status == MemberStatus.active &&
229:         member.id != viewer.id &&
230:         member.role != Roles.projectOwner;
231:     return MemberCard(
232:       member: member,
233:       showStatus: isOwnerOrAdmin(viewer.role),
234:       showRole: isAdmin(viewer.role),
235:       canConfirm: canConfirm,
236:       onConfirm: () => _confirm(context, ref, member),
237:       canChangeRole: canChangeRole,
238:       onRoleChanged: (role) => _changeRole(context, ref, member, role),
239:     );
240:   }
241: 
242:   /// Applies an admin-only role change; granting admin asks for confirmation.
243:   Future<void> _changeRole(
244:     BuildContext context,
245:     WidgetRef ref,
246:     Account member,
247:     String role,
248:   ) async {
249:     if (role == Roles.admin) {
250:       final confirmed = await showDialog<bool>(
251:         context: context,
252:         builder: (context) => AlertDialog(
253:           title: const Text('Give admin access?'),
254:           content: Text(
255:             '${member.name} will be able to manage every project, member '
256:             'and role.',
257:           ),
258:           actions: [
259:             TextButton(
260:               onPressed: () => Navigator.pop(context, false),
261:               child: const Text('Cancel'),
262:             ),
263:             FilledButton(
264:               onPressed: () => Navigator.pop(context, true),
265:               child: const Text('Make admin'),
266:             ),
267:           ],
268:         ),
269:       );
270:       if (confirmed != true || !context.mounted) {
271:         return;
272:       }
273:     }
274:     try {
275:       await ref
276:           .read(memberServiceProvider)
277:           .changeRole(userId: member.id, role: role);
278:     } catch (e) {
279:       if (context.mounted) {
280:         showAppSnackBar(context, userMessage(e));
281:       }
282:     }
283:   }
284: 
285:   Future<void> _confirm(
286:     BuildContext context,
287:     WidgetRef ref,
288:     Account member,
289:   ) async {
290:     try {
291:       await ref.read(memberServiceProvider).confirmUser(userId: member.id);
292:     } catch (e) {
293:       if (context.mounted) {
294:         showAppSnackBar(context, userMessage(e));
295:       }
296:     }
297:   }
298: 
299:   Future<void> _addDialog(
300:     BuildContext context,
301:     WidgetRef ref,
302:     Account viewer,
303:   ) async {
304:     final admin = isAdmin(viewer.role);
305:     // Owners add users to their own project only; the dialog hides the
306:     // project selector and does not need the projects list.
307:     List<Project> projects = const <Project>[];
308:     if (admin) {
309:       try {
310:         final projectState = ref.read(projectListProvider);
311:         if (projectState.hasValue) {
312:           projects = projectState.value!.items;
313:         }
314:       } catch (e) {
315:         if (context.mounted) {
316:           showAppSnackBar(context, userMessage(e));
317:         }
318:         return;
319:       }
320:       if (!context.mounted) {
321:         return;
322:       }
323:     }
324:     final draft = await showDialog<MemberDraft>(
325:       context: context,
326:       builder: (_) => AddMemberDialog(
327:         projects: projects,
328:         isAdmin: admin,
329:         ownerProjectId: viewer.projectId,
330:       ),
331:     );
332:     if (draft == null || !context.mounted) {
333:       return;
334:     }
335:     try {
336:       await ref
337:           .read(memberServiceProvider)
338:           .createUser(
339:             name: draft.name,
340:             email: draft.email,
341:             password: draft.password,
342:             position: draft.position,
343:             projectId: draft.projectId,
344:           );
345:     } catch (e) {
346:       if (context.mounted) {
347:         showAppSnackBar(context, userMessage(e));
348:       }
349:     }
350:   }
351: }

