class PageResult<T> { ... }

abstract class PaginatedNotifier<T> extends AsyncNotifier<PaginatedList<T>> {
  int get pageSize => 20;
  Object keyOf(T item);
  Future<PageResult<T>> fetchPage({required int offset, required int limit});

  int _generation = 0;

  @override
  Future<PaginatedList<T>> build() async {
    // Rebuild the feed when the signed-in account changes.
    ref.watch(sessionUserIdProvider);
    // Mutations ping DataSync; reload the first page without a spinner.
    ref.listen(dataSyncTickProvider, (_, _) => _reload());
    final page = await fetchPage(offset: 0, limit: pageSize);
    return _page(page, hasMore: page.items.length < page.total);
  }

  PaginatedList<T> _page(PageResult<T> page, {required bool hasMore, int number = 1}) =>
      PaginatedList<T>(
        items: page.items,
        page: number,
        pageSize: pageSize,
        hasMore: hasMore,
      );

  Future<void> loadMore() async {
    final current = state.valueOrNull;
    if (current == null || current.isLoading || current.isLoadingMore || !current.hasMore) {
      return;
    }
    final generation = _generation;
    state = AsyncData(current.copyWith(isLoadingMore: true));
    try {
      final page = await fetchPage(offset: current.items.length, limit: pageSize);
      if (!ref.mounted || generation != _generation) return;
      final seen = current.items.map(keyOf).toSet();
      final merged = [
        ...current.items,
        ...page.items.where((item) => !seen.contains(keyOf(item))),
      ];
      state = AsyncData(PaginatedList<T>(
        items: merged,
        page: current.page + 1,
        pageSize: pageSize,
        hasMore: merged.length < page.total,
      ));
    } catch (_) {
      if (!ref.mounted || generation != _generation) return;
      state = AsyncData(current.copyWith(isLoadingMore: false));
    }
  }

  Future<void> refresh() async {
    final generation = ++_generation;
    try {
      final page = await fetchPage(offset: 0, limit: pageSize);
      if (!ref.mounted || generation != _generation) return;
      state = AsyncData(_page(page, hasMore: page.items.length < page.total));
    } catch (e, st) {
      if (!ref.mounted || generation != _generation) return;
      state = AsyncError(e, st);
    }
  }

  Future<void> _reload() async {
    if (state.isLoading) return;
    final generation = ++_generation;
    try {
      final page = await fetchPage(offset: 0, limit: pageSize);
      if (!ref.mounted || generation != _generation) return;
      state = AsyncData(_page(page, hasMore: page.items.length < page.total));
    } catch (_) {
      // Keep the last good page; a later ping or pull-to-refresh retries.
    }
  }
}
```

