import { clickLabel, clickText, fill, login, pageText, shot, waitForText } from './lib.mjs';
import { connect, evaluate, sleep } from './cdp.mjs';

const API = 'http://localhost:8000/api/v1';
const { send } = await connect();

function assert(condition, message, detail = '') {
  if (!condition) throw new Error(`${message}\n${String(detail).slice(0, 2000)}`);
}

async function api(method, path, body, token) {
  const response = await fetch(`${API}${path}`, {
    method,
    headers: {
      'Content-Type': 'application/json',
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
    },
    body: body ? JSON.stringify(body) : undefined,
  });
  const text = await response.text();
  let json = null;
  try { json = text ? JSON.parse(text) : null; } catch { json = text; }
  return { status: response.status, json };
}

// --- E1: first account becomes admin, created from the UI ---
await waitForText('Log in', 30000);
await clickText('^Create an account$');
await sleep(1500);
await waitForText('Sign up', 10000);
await fill('Name', 'Admin E2E');
await fill('Email', 'admin@e2e.test');
await fill('Password', 'Passw0rd!23');
await shot('e1-signup-filled');
await clickText('^Sign up$');
await waitForText('Projects', 30000);
await sleep(1000);
await shot('e1-admin-home');

let text = await pageText();
assert(/Projects/.test(text), 'Admin home did not open Projects', text);

// --- Create project Alpha from the UI ---
await clickText('^Create project$');
await sleep(1200);
await waitForText('New project', 10000);
const dialogText = await pageText();
assert(/New project/.test(dialogText), 'New project dialog missing', dialogText);
await fill('Name', 'Alpha');
await fill('Description', 'First project');
await clickText('^Create$');
await waitForText('Alpha', 20000);
await sleep(1000);
await shot('e1-alpha-created');

const adminLogin = await api('POST', '/auth/login', { email: 'admin@e2e.test', password: 'Passw0rd!23' });
assert(adminLogin.status === 200, 'Admin API login failed', adminLogin);
const adminToken = adminLogin.json.access_token;
const adminId = adminLogin.json.account.id;

const projects = (await api('GET', '/projects')).json;
const alpha = projects.items.find((p) => p.name === 'Alpha');
assert(alpha, 'Alpha project missing', projects);
assert(adminLogin.json.account.role === 'admin', 'First account is not admin', adminLogin.json.account);

// --- Beta + members + owners through the API (accepted shortcut) ---
const beta = (await api('POST', '/projects', { name: 'Beta', description: 'Second project' }, adminToken)).json;

async function addMember(name, email, projectId, position) {
  const response = await api('POST', '/members', {
    name, email, password: 'Passw0rd!23', position, project_id: projectId, role: 'user',
  }, adminToken);
  assert(response.status === 201, `Cannot create ${name}`, response);
  return response.json;
}

const alice = await addMember('Alice', 'alice@e2e.test', alpha.id, 'Lead');
const bob = await addMember('Bob', 'bob@e2e.test', alpha.id, 'Developer');
const bruno = await addMember('Bruno', 'bruno@e2e.test', beta.id, 'Developer');
const assignedAlpha = await api('POST', `/projects/${alpha.id}/assign-owner`, { owner_id: alice.id }, adminToken);
const assignedBeta = await api('POST', `/projects/${beta.id}/assign-owner`, { owner_id: bruno.id }, adminToken);
assert(assignedAlpha.status === 200, 'Alpha owner assignment failed', assignedAlpha);
assert(assignedBeta.status === 200, 'Beta owner assignment failed', assignedBeta);

const carolSignup = await api('POST', '/auth/signup', {
  name: 'Carol', email: 'carol@e2e.test', password: 'Passw0rd!23', position: 'Designer', project_id: alpha.id,
});
assert(carolSignup.status === 201, 'Carol signup failed', carolSignup);
assert(carolSignup.json.status === 'pending', 'Carol should be pending', carolSignup.json);

// --- Verify the UI reflects the prepared data ---
await send('Page.reload');
await sleep(4000);
for (let i = 0; i < 40; i += 1) {
  const ready = await evaluate(send, `!!document.querySelector('flt-semantics-placeholder')`);
  if (ready) {
    await evaluate(send, `document.querySelector('flt-semantics-placeholder').click()`);
    break;
  }
  await sleep(500);
}
await sleep(1500);
await waitForText('Alpha', 30000);
await clickText('^Beta$');
await sleep(1500);
text = await pageText();
assert(/Beta/.test(text), 'Beta missing in Projects', text);
await clickLabel('^Members$');
await sleep(2000);
await waitForText('Carol', 20000);
text = await pageText();
for (const name of ['Admin E2E', 'Alice', 'Bob', 'Bruno', 'Carol']) {
  assert(new RegExp(name).test(text), `Roster is missing ${name}`, text);
}
await shot('e1-admin-members');

console.log('E1 PASSED: first UI signup is admin, Alpha created in the UI, Beta/members/owners prepared via API and visible.');
console.log(JSON.stringify({ adminId, alphaId: alpha.id, betaId: beta.id, aliceId: alice.id, bobId: bob.id, brunoId: bruno.id, carolId: carolSignup.json.id }));
process.exit(0);

