import { pageText, shot } from './lib.mjs';

const { send } = await connect();
console.log(await pageText());
await screenshot(send, 'C:/Users/CHEDI/AppData/Local/Temp/opencode/e2e-run3/after-e1-failure.png');
process.exit(0);

