import { clickLabel, pageText, shot, waitForText } from './lib.mjs';

const API = 'http://localhost:8000/api/v1';
function assert(condition, message, detail = '') {
  if (!condition) throw new Error(`${message}\n${String(detail).slice(0, 2000)}`);
}
async function api(method, path, body, token) {
  const response = await fetch(`${API}${path}`, {
    method,
    headers: {
      'Content-Type': 'application/json',
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
    },
    body: body ? JSON.stringify(body) : undefined,
  });
  return { status: response.status, json: await response.json() };
}

await waitForText('Projects', 30000);
let text = await pageText();
assert(/Alpha/.test(text) && /Beta/.test(text), 'Projects list is missing Alpha/Beta', text);
assert(/Alice/.test(text) && /Bruno/.test(text), 'Owner assignment is not visible', text);
await shot('e1-admin-projects');

await clickLabel('^Members$');
await waitForText('Carol', 20000);
text = await pageText();
for (const name of ['Admin E2E', 'Alice', 'Bob', 'Bruno', 'Carol']) {
  assert(new RegExp(name).test(text), `Roster is missing ${name}`, text);
}
await shot('e1-admin-members');

const admin = (await api('POST', '/auth/login', { email: 'admin@e2e.test', password: 'Passw0rd!23' })).json;
assert(admin.account.role === 'admin', 'First account is not admin', admin.account);
const projects = (await api('GET', '/projects')).json.items;
const alpha = projects.find((p) => p.name === 'Alpha');
const beta = projects.find((p) => p.name === 'Beta');
const members = (await api('GET', '/members', null, admin.access_token)).json.items;
const byEmail = Object.fromEntries(members.map((m) => [m.email, m]));
for (const email of ['alice@e2e.test', 'bob@e2e.test', 'bruno@e2e.test', 'carol@e2e.test']) {
  assert(byEmail[email], `Missing member ${email}`, members);
}
assert(byEmail['alice@e2e.test'].role === 'project_owner', 'Alice is not owner', byEmail['alice@e2e.test']);
assert(byEmail['carol@e2e.test'].status === 'pending', 'Carol is not pending', byEmail['carol@e2e.test']);

console.log('E1 PASSED: first UI signup is admin, Alpha created in the UI, Beta/members/owners visible in the UI.');
console.log(JSON.stringify({
  adminId: admin.account.id,
  alphaId: alpha.id,
  betaId: beta.id,
  aliceId: byEmail['alice@e2e.test'].id,
  bobId: byEmail['bob@e2e.test'].id,
  brunoId: byEmail['bruno@e2e.test'].id,
  carolId: byEmail['carol@e2e.test'].id,
}));
process.exit(0);

