1: // Pure-Dart business rules. No Flutter, no database: unit-testable in isolation.
2: //
3: // Mirrors PROJECT_BRIEF.md and docs/ARCHITECTURE_PROPOSAL.md. The services
4: // in `lib/services/` enforce these rules against real rows; the checks here
5: // are the single definition of each rule.
6: 
7: // Roles (cumulative: admin > project owner > team lead > user > viewer).
8: abstract final class Roles {
9:   static const admin = 'admin';
10:   static const projectOwner = 'project_owner';
11:   static const teamLead = 'team_lead';
12:   static const user = 'user';
13:   static const viewer = 'viewer';
14: }
15: 
16: // Membership states.
17: abstract final class MemberStatus {
18:   static const pending = 'pending';
19:   static const active = 'active';
20: }
21: 
22: // Task states.
23: abstract final class TaskStatus {
24:   static const todo = 'todo';
25:   static const completed = 'completed';
26: }
27: 
28: /// A task is assigned either to its project as a whole ([assigneeId] null)
29: /// or to exactly one person, who must belong to the task's project.
30: void validateTaskAssignment({
31:   required int taskProjectId,
32:   required int? assigneeId,
33:   required int? assigneeProjectId,
34: }) {
35:   if (assigneeId != null && assigneeProjectId != taskProjectId) {
36:     throw ArgumentError('Assignee must belong to the task project.');
37:   }
38: }
39: 
40: /// Only active accounts may log in. Pending accounts wait for owner approval.
41: bool canLogIn(String status) => status == MemberStatus.active;
42: 
43: bool isAdmin(String role) => role == Roles.admin;
44: 
45: bool isOwnerOrAdmin(String role) =>
46:     role == Roles.admin || role == Roles.projectOwner;
47: 
48: bool isViewer(String role) => role == Roles.viewer;
49: 
50: bool isTeamLead(String role) => role == Roles.teamLead;
51: 
52: /// Throws [StateError] unless [role] is not a viewer (i.e. can mutate).
53: void requireCanMutate(String role) {
54:   if (isViewer(role)) {
55:     throw StateError('Viewers cannot make changes.');
56:   }
57: }
58: 
59: /// Tabs visible for a role, in display order.
60: ///
61: /// Admins have no personal task list (they cannot be assignees); the
62: /// "mine" tab is for project owners and users.
63: List<String> visibleTabs(String role) {
64:   if (isAdmin(role)) {
65:     return const ['projects', 'members', 'tasks', 'planner', 'dashboard'];
66:   }
