import { clickAt, connect, evaluate } from './cdp.mjs';
import { clickLabel, clickText, login, pageText, shot, waitForText } from './lib.mjs';
import { sleep } from './cdp.mjs';

const API = 'http://localhost:8000/api/v1';
const { send } = await connect();

function assert(condition, message, detail = '') {
  if (!condition) throw new Error(`${message}\n${String(detail).slice(0, 2000)}`);
}

async function apiLogin(email) {
  const response = await fetch(`${API}/auth/login`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ email, password: 'Passw0rd!23' }),
  });
  return { status: response.status, json: await response.json() };
}

async function logout() {
  const avatar = await evaluate(send, `(() => {
    for (const el of document.querySelectorAll('flt-semantics[flt-tappable]')) {
      const r = el.getBoundingClientRect();
      if (r.y < 60 && r.x > 900 && r.width > 20) return { x: r.x + r.width / 2, y: r.y + r.height / 2 };
    }
    return null;
  })()`);
  assert(avatar, 'Avatar not found');
  await clickAt(send, avatar.x, avatar.y);
  await sleep(1000);
  await clickText('^Log out$');
  await waitForText('Log in', 20000);
  await sleep(800);
}

await waitForText('Projects', 20000);
await logout();

// --- Carol is pending: login is refused with the membership message ---
await login('carol@e2e.test', 'Passw0rd!23');
await waitForText('waiting for project owner confirmation', 15000);
let text = await pageText();
assert(/waiting for project owner confirmation/i.test(text), 'Pending login message missing', text);
assert(!/Projects/.test(text), 'Carol reached the app while pending', text);
await shot('e2-carol-blocked');

// --- Alice (project owner) confirms Carol from Members ---
await login('alice@e2e.test', 'Passw0rd!23');
await waitForText('Members', 30000);
await sleep(1500);
text = await pageText();
assert(/Carol/.test(text), 'Alice cannot see Carol', text);
assert(/Confirm/.test(text), 'Confirm action missing for Alice', text);
await clickText('^Confirm$');
await sleep(2000);
await shot('e2-carol-confirmed');

const carol = await apiLogin('carol@e2e.test');
assert(carol.status === 200, 'Carol login still refused by the API', carol);

// --- Carol logs in and sees Alpha only ---
await logout();
await login('carol@e2e.test', 'Passw0rd!23');
await waitForText('Members', 30000);
await sleep(1500);
text = await pageText();
assert(/Alice/.test(text) && /Bob/.test(text) && /Carol/.test(text), 'Carol roster is incomplete', text);
assert(!/Bruno/.test(text), 'Carol sees Bruno from Beta', text);
const nav = await evaluate(send, `[...document.querySelectorAll('flt-semantics[role="tab"]')]
  .map((el) => el.getAttribute('aria-label') || '')`);
assert(!nav.includes('Projects'), 'Carol should not see Projects', nav);
assert(nav.includes('Mine'), 'Carol should see Mine', nav);
await shot('e2-carol-home');

console.log('E2 PASSED: pending login blocked, Alice confirmed Carol in the UI, Carol sees Alpha only.');
console.log('nav:', JSON.stringify(nav));
process.exit(0);

