const nodes = await evaluate(send, `[...document.querySelectorAll('flt-semantics')].map(el => {
  const r = el.getBoundingClientRect();
  return { label: el.getAttribute('aria-label')||'', text: el.textContent.trim(), role: el.getAttribute('role'), tappable: el.hasAttribute('flt-tappable'), x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) };
}).filter(n => n.w && n.h)`);
console.log(JSON.stringify(nodes, null, 2));
