export async function fill(label, value) {
  const selector = `input[aria-label="${label}"],textarea[aria-label="${label}"]`;
  const rect = await evaluate(send, `(() => {
    const el = document.querySelector(${JSON.stringify(selector)});
    if (!el) return null;
    const r = el.getBoundingClientRect();
    if (!r.width || !r.height) return null;
    return { x: r.x + r.width / 2, y: r.y + r.height / 2 };
  })()`);
  if (!rect) throw new Error(`No input labelled ${label}`);
  await clickAt(send, rect.x, rect.y);
  await sleep(250);
  // Select the current content so the new text replaces it instead of
  // appending to a prefilled field left over from a previous attempt.
  await send('Input.dispatchKeyEvent', {
    type: 'keyDown', key: 'a', code: 'KeyA', modifiers: 2, windowsVirtualKeyCode: 65,
  });
  await send('Input.dispatchKeyEvent', {
    type: 'keyUp', key: 'a', code: 'KeyA', modifiers: 2, windowsVirtualKeyCode: 65,
  });
  await typeText(send, value);
  await sleep(250);
  const actual = await evaluate(send, `(() => {
    const el = document.querySelector(${JSON.stringify(selector)});
    return el ? el.value : null;
  })()`);
  if (actual !== value) throw new Error(`Fill ${label} expected ${value}, got ${actual}`);
  return actual;
}

