import { clickAt, connect, evaluate, sleep } from './cdp.mjs';
import { clickLabel, clickText, fill, login, pageText, shot, waitForText } from './lib.mjs';

const API = 'http://localhost:8000/api/v1';
const { send } = await connect();

function assert(condition, message, detail = '') {
  if (!condition) throw new Error(`${message}\n${String(detail).slice(0, 2000)}`);
}

async function api(method, path, body, token) {
  const response = await fetch(`${API}${path}`, {
    method,
    headers: {
      'Content-Type': 'application/json',
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
    },
    body: body ? JSON.stringify(body) : undefined,
  });
  const text = await response.text();
  let json = null;
  try { json = text ? JSON.parse(text) : null; } catch { json = text; }
  return { status: response.status, json };
}

async function logout() {
  const avatar = await evaluate(send, `(() => {
    for (const el of document.querySelectorAll('flt-semantics[flt-tappable]')) {
      const label = el.getAttribute('aria-label') || '';
      const r = el.getBoundingClientRect();
      if (r.y < 60 && r.x > 900 && r.width > 20 && !/Notifications|Theme/.test(label)) {
        return { x: r.x + r.width / 2, y: r.y + r.height / 2 };
      }
    }
    return null;
  })()`);
  assert(avatar, 'Avatar not found');
  await clickAt(send, avatar.x, avatar.y);
  await sleep(900);
  await clickLabel('^Log out$');
  await waitForText('Log in', 20000);
  await sleep(600);
}

async function cardRect(title) {
  const rect = await evaluate(send, `(() => {
    for (const el of document.querySelectorAll('flt-semantics')) {
      const text = el.textContent.trim();
      if (!text.includes(${JSON.stringify(title)})) continue;
      const r = el.getBoundingClientRect();
      if (r.width < 200 || r.height < 30) continue;
      return { x: r.x, y: r.y, w: r.width, h: r.height };
    }
    return null;
  })()`);
  assert(rect, `Task card not found: ${title}`);
  return rect;
}

async function clickInCard(title, matcher) {
  const rect = await cardRect(title);
  const point = await evaluate(send, `(() => {
    const card = ${JSON.stringify(rect)};
    const re = new RegExp(${JSON.stringify(matcher)});
    for (const el of document.querySelectorAll('flt-semantics[flt-tappable]')) {
      const label = el.getAttribute('aria-label') || '';
      const text = el.textContent.trim();
      if (!re.test(label) && !re.test(text)) continue;
      const r = el.getBoundingClientRect();
      const cx = r.x + r.width / 2;
      const cy = r.y + r.height / 2;
      if (cx < card.x || cx > card.x + card.w) continue;
      if (cy < card.y - 4 || cy > card.y + card.h + 4) continue;
      return { x: cx, y: cy };
    }
    return null;
  })()`);
  assert(point, `No ${matcher} inside ${title}`);
  await clickAt(send, point.x, point.y);
}

async function toggleTask(title) {
  const rect = await cardRect(title);
  await clickAt(send, rect.x + 24, rect.y + rect.h / 2);
  await sleep(1500);
}

async function apiTask(token, body) {
  const response = await api('POST', '/tasks', body, token);
  assert(response.status === 201, 'Task creation failed', response);
  return response.json();
}

let current = await pageText();
if (current.includes('Members')) {
  await logout();
}
await login('alice@e2e.test', 'Passw0rd!23');
await waitForText('Members', 30000);
await clickLabel('^Tasks$');
await waitForText('All', 20000);
await sleep(1000);

// --- Create a task from the UI ---
await clickText('^Add task$');
await waitForText('New task', 10000);
await fill('Title', 'Project kickoff');
await fill('Description (optional)', 'Kick off Alpha');
await clickText('^Priority$');
await sleep(600);
await clickText('^High$');
await sleep(600);
await shot('e3-new-task');
await clickText('^Create$');
await waitForText('Project kickoff', 20000);
await sleep(1200);
await shot('e3-created');

let text = await pageText();
assert(/Project kickoff/.test(text), 'Created task missing', text);

// --- Edit the task from the UI ---
await clickText('Project kickoff');
await waitForText('Edit task', 10000);
await fill('Title', 'Project kickoff updated');
await clickText('^Save$');
await waitForText('Project kickoff updated', 20000);
await sleep(1000);
await shot('e3-edited');

// --- Complete, reopen, delete, undo ---
await toggleTask('Project kickoff updated');
await waitForText('Done', 10000);
text = await pageText();
assert(/Project kickoff updated/.test(text), 'Task disappeared after completion', text);
await shot('e3-completed');

await toggleTask('Project kickoff updated');
await sleep(800);

await clickInCard('Project kickoff updated', '^Delete$');
await waitForText('Task deleted', 10000);
await shot('e3-deleted');
text = await pageText();
assert(!/Project kickoff updated/.test(text), 'Deleted task still listed', text);
await clickText('^Undo$');
await waitForText('Project kickoff updated', 20000);
await sleep(800);

// --- Date variants for the filters (API) ---
const admin = (await api('POST', '/auth/login', { email: 'admin@e2e.test', password: 'Passw0rd!23' })).json;
const alpha = (await api('GET', '/projects')).json.items.find((p) => p.name === 'Alpha');
const today = new Date();
const iso = (d) => d.toISOString().slice(0, 10);
const yesterday = new Date(today.getTime() - 86400000);
const nextWeek = new Date(today.getTime() + 7 * 86400000);
await apiTask(admin.access_token, {
  project_id: alpha.id, title: 'Alpha overdue', priority: 'low', due_date: iso(yesterday),
});
await apiTask(admin.access_token, {
  project_id: alpha.id, title: 'Alpha today', priority: 'medium', due_date: iso(today),
});
await apiTask(admin.access_token, {
  project_id: alpha.id, title: 'Alpha upcoming', priority: 'high', due_date: iso(nextWeek),
});

// Refresh the list through pull-to-refresh semantics: switch tabs and back.
await clickLabel('^Mine$');
await sleep(800);
await clickLabel('^Tasks$');
await waitForText('Alpha overdue', 20000);
await sleep(800);

async function filter(label, expected, forbidden) {
  await clickText(`^${label}$`);
  await sleep(900);
  const body = await pageText();
  assert(new RegExp(expected).test(body), `${label} filter is missing ${expected}`, body);
  if (forbidden) {
    assert(!new RegExp(forbidden).test(body), `${label} filter leaks ${forbidden}`, body);
  }
  await shot(`e3-filter-${label.toLowerCase()}`);
}

await filter('Overdue', 'Alpha overdue', 'Alpha upcoming');
await filter('Upcoming', 'Alpha upcoming', 'Alpha overdue');
await filter('Today', 'Alpha today', 'Alpha overdue');
await filter('All', 'Alpha today', 'Beta secret');

console.log('E3 PASSED: UI create/edit/complete/reopen/delete/undo and the four date filters work.');
process.exit(0);

