import { clickAt, connect, evaluate, sleep } from './cdp.mjs';
import { clickLabel, login, pageText, shot, waitForText } from './lib.mjs';

const API = 'http://localhost:8000/api/v1';
const { send } = await connect();

function assert(condition, message, detail = '') {
  if (!condition) throw new Error(`${message}\n${String(detail).slice(0, 2000)}`);
}

async function api(method, path, body, token) {
  const response = await fetch(`${API}${path}`, {
    method,
    headers: {
      'Content-Type': 'application/json',
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
    },
    body: body ? JSON.stringify(body) : undefined,
  });
  const text = await response.text();
  let json = null;
  try { json = text ? JSON.parse(text) : null; } catch { json = text; }
  return { status: response.status, json };
}

async function logout() {
  const avatar = await evaluate(send, `(() => {
    for (const el of document.querySelectorAll('flt-semantics[flt-tappable]')) {
      const label = el.getAttribute('aria-label') || '';
      const r = el.getBoundingClientRect();
      if (r.y < 60 && r.x > 900 && r.width > 20 && !/Notifications|Theme/.test(label)) {
        return { x: r.x + r.width / 2, y: r.y + r.height / 2 };
      }
    }
    return null;
  })()`);
  assert(avatar, 'Avatar not found');
  await clickAt(send, avatar.x, avatar.y);
  await sleep(900);
  await clickLabel('^Log out$');
  await waitForText('Log in', 20000);
  await sleep(600);
}

async function cardRect(title) {
  const rect = await evaluate(send, `(() => {
    for (const el of document.querySelectorAll('flt-semantics')) {
      const text = el.textContent.trim();
      const label = el.getAttribute('aria-label') || '';
      if (!text.includes(${JSON.stringify(title)}) && !label.includes(${JSON.stringify(title)})) continue;
      const r = el.getBoundingClientRect();
      if (r.width < 200 || r.height < 30) continue;
      return { x: r.x, y: r.y, w: r.width, h: r.height };
    }
    return null;
  })()`);
  assert(rect, `Task card not found: ${title}`);
  return rect;
}

// --- Beta task + a task assigned to Bob (API setup) ---
const admin = (await api('POST', '/auth/login', { email: 'admin@e2e.test', password: 'Passw0rd!23' })).json;
const projects = (await api('GET', '/projects')).json.items;
const alpha = projects.find((p) => p.name === 'Alpha');
const beta = projects.find((p) => p.name === 'Beta');
const members = (await api('GET', '/members?limit=100', null, admin.access_token)).json.items;
const bob = members.find((m) => m.email === 'bob@e2e.test');
const iso = (offsetDays) => {
  const d = new Date();
  d.setDate(d.getDate() + offsetDays);
  return d.toISOString().slice(0, 10);
};
const today = iso(0);
const betaTask = await api('POST', '/tasks', {
  project_id: beta.id, title: 'Beta secret', priority: 'medium',
}, admin.access_token);
assert(betaTask.status === 201, 'Cannot create Beta secret', betaTask);
const bobTask = await api('POST', '/tasks', {
  project_id: alpha.id, title: 'Bob review', priority: 'low', due_date: today, assignee_id: bob.id,
}, admin.access_token);
assert(bobTask.status === 201, 'Cannot create Bob review', bobTask);

// --- Bob sees Alpha only ---
let current = await pageText();
if (/Tasks|Members|Planner|Dashboard/.test(current)) {
  await logout();
}
await login('bob@e2e.test', 'Passw0rd!23');
await waitForText('Members', 30000);
await sleep(1200);
const nav = await evaluate(send, `[...document.querySelectorAll('flt-semantics[role="tab"]')]
  .map((el) => el.getAttribute('aria-label') || '')`);
assert(nav.includes('Mine'), 'Bob is missing Mine', nav);
assert(!nav.includes('Projects'), 'Bob should not see Projects', nav);

await clickLabel('^Tasks$');
await waitForText('Bob review', 20000);
await sleep(800);
let text = await pageText();
for (const title of ['Bob review', 'Alpha overdue', 'Alpha today', 'Alpha upcoming']) {
  assert(new RegExp(title).test(text), `Bob cannot see ${title}`, text);
}
assert(!/Beta secret/.test(text), 'Bob sees the Beta task', text);
await shot('e4-bob-all');

async function filter(label, expected, forbidden) {
  await clickLabel(`^${label}$`);
  await sleep(900);
  const body = await pageText();
  assert(new RegExp(expected).test(body), `${label} is missing ${expected}`, body);
  if (forbidden) assert(!new RegExp(forbidden).test(body), `${label} leaks ${forbidden}`, body);
}

await filter('Today', 'Alpha today', 'Alpha overdue');
await filter('Overdue', 'Alpha overdue', 'Alpha upcoming');
await filter('Upcoming', 'Alpha upcoming', 'Alpha overdue');
await filter('All', 'Bob review', 'Beta secret');

// --- Mine shows only Bob's task and allows completing it ---
await clickLabel('^Mine$');
await waitForText('Bob review', 20000);
await sleep(900);
text = await pageText();
assert(!/Beta secret/.test(text), 'Mine leaks the Beta task', text);
assert(!/Alpha today/.test(text), 'Mine leaks an unassigned task', text);
await shot('e4-bob-mine');

const rect = await cardRect('Bob review');
await clickAt(send, rect.x + 24, rect.y + rect.h / 2);
await sleep(1500);
const after = await pageText();
assert(/1\nDone|Done/.test(after), 'Completion did not refresh the stats', after);
await shot('e4-bob-mine-completed');

await clickAt(send, rect.x + 24, rect.y + rect.h / 2);
await sleep(1200);

console.log('E4 PASSED: Bob sees Alpha only, the filters match, Mine shows only his task, and completion works.');
process.exit(0);

