async function hasRoleButton(name) {
  const card = await memberCard(name);
  return evaluate(send, `(() => {
    const card = ${JSON.stringify(card)};
    for (const el of document.querySelectorAll('flt-semantics[flt-tappable]')) {
      if ((el.getAttribute('aria-label') || '') !== 'Change role') continue;
      const r = el.getBoundingClientRect();
      const cx = r.x + r.width / 2;
      const cy = r.y + r.height / 2;
      if (cx >= card.x && cx <= card.x + card.w && cy >= card.y && cy <= card.y + card.h) return true;
    }
    return false;
  })()`);
}

async function changeRole(name, role) {
  const card = await memberCard(name);
