import { clickAt, connect, evaluate, sleep } from './cdp.mjs';
import { clickLabel, clickText, login, pageText, shot, waitForText } from './lib.mjs';

const API = 'http://localhost:8000/api/v1';
const { send } = await connect();

function assert(condition, message, detail = '') {
  if (!condition) throw new Error(`${message}\n${String(detail).slice(0, 2000)}`);
}

async function api(method, path, body, token) {
  const response = await fetch(`${API}${path}`, {
    method,
    headers: {
      'Content-Type': 'application/json',
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
    },
    body: body ? JSON.stringify(body) : undefined,
  });
  const text = await response.text();
  let json = null;
  try { json = text ? JSON.parse(text) : null; } catch { json = text; }
  return { status: response.status, json };
}

async function logout() {
  const avatar = await evaluate(send, `(() => {
    for (const el of document.querySelectorAll('flt-semantics[flt-tappable]')) {
      const label = el.getAttribute('aria-label') || '';
      const r = el.getBoundingClientRect();
      if (r.y < 60 && r.x > 900 && r.width > 20 && !/Notifications|Theme/.test(label)) {
        return { x: r.x + r.width / 2, y: r.y + r.height / 2 };
      }
    }
    return null;
  })()`);
  assert(avatar, 'Avatar not found');
  await clickAt(send, avatar.x, avatar.y);
  await sleep(900);
  await clickLabel('^Log out$');
  await waitForText('Log in', 20000);
  await sleep(600);
}

async function navLabels() {
  return evaluate(send, `[...document.querySelectorAll('flt-semantics[role="tab"]')]
    .map((el) => el.getAttribute('aria-label') || '')`);
}

/** Types into the Members search box; the box has a placeholder, no aria-label. */
async function searchMember(value) {
  const rect = await evaluate(send, `(() => {
    const el = document.querySelector('input[placeholder="Search members"]');
    if (!el) return null;
    const r = el.getBoundingClientRect();
    return { x: r.x + r.width / 2, y: r.y + r.height / 2 };
  })()`);
  assert(rect, 'Members search box not found');
  await clickAt(send, rect.x, rect.y);
  await sleep(250);
  await send('Input.dispatchKeyEvent', {
    type: 'keyDown', key: 'a', code: 'KeyA', modifiers: 2, windowsVirtualKeyCode: 65,
  });
  await send('Input.dispatchKeyEvent', {
    type: 'keyUp', key: 'a', code: 'KeyA', modifiers: 2, windowsVirtualKeyCode: 65,
  });
  for (const char of value) {
    await send('Input.dispatchKeyEvent', { type: 'keyDown', text: char, key: char });
    await send('Input.dispatchKeyEvent', { type: 'keyUp', key: char });
    await sleep(40);
  }
  await sleep(1200);
  const actual = await evaluate(send, `document.querySelector('input[placeholder="Search members"]')?.value`);
  assert(actual === value, `Search box expected ${value}, got ${actual}`);
}

/** Clicks the "Change role" menu on the only card currently shown. */
async function openRoleMenu() {
  const button = await evaluate(send, `(() => {
    for (const el of document.querySelectorAll('flt-semantics[flt-tappable]')) {
      const label = (el.getAttribute('aria-label') || '').trim();
      const text = el.textContent.trim();
      if (label !== 'Change role' && text !== 'Change role') continue;
      const r = el.getBoundingClientRect();
      if (r.width && r.height) return { x: r.x + r.width / 2, y: r.y + r.height / 2 };
    }
    return null;
  })()`);
  assert(button, 'Change role button not found');
  await clickAt(send, button.x, button.y);
  await sleep(900);
}

async function visibleRoleButtons() {
  return evaluate(send, `[...document.querySelectorAll('flt-semantics[flt-tappable]')]
    .filter((el) => {
      const r = el.getBoundingClientRect();
      const label = (el.getAttribute('aria-label') || '').trim();
      const text = el.textContent.trim();
      return r.width && r.height && (label === 'Change role' || text === 'Change role');
    }).length`);
}

async function apiRole(email) {
  const admin = (await api('POST', '/auth/login', { email: 'admin@e2e.test', password: 'Passw0rd!23' })).json;
  const members = (await api('GET', '/members?limit=100', null, admin.access_token)).json.items;
  const member = members.find((m) => m.email === email);
  return member ? member.role : null;
}

async function waitApiRole(email, expected) {
  for (let i = 0; i < 40; i += 1) {
    if ((await apiRole(email)) === expected) return;
    await sleep(300);
  }
  throw new Error(`${email} role never became ${expected} (still ${await apiRole(email)})`);
}

async function changeRole(name, role) {
  await searchMember(name);
  assert((await visibleRoleButtons()) === 1, `Expected exactly one Change role button for ${name}`);
  await openRoleMenu();
  await clickLabel(`^${role}$`);
  await sleep(1000);
}

let current = await pageText();
if (/Tasks|Members|Planner|Dashboard/.test(current)) {
  await logout();
}
await login('admin@e2e.test', 'Passw0rd!23');
await waitForText('Projects', 30000);
await clickLabel('^Members$');
await waitForText('Bob', 20000);
await sleep(1200);
await shot('e5-members');

// The admin cannot change their own role, and an owner is managed through
// Projects -> Assign owner instead of the role menu.
await searchMember('Admin E2E');
assert((await visibleRoleButtons()) === 0, 'Admin has a role menu on their own row');
await shot('e5-admin-no-role-menu');

await searchMember('Alice');
assert((await visibleRoleButtons()) === 0, 'Owner row has a role menu');
await shot('e5-owner-no-role-menu');

// --- Team lead ---
await changeRole('Bob', 'Team lead');
await waitApiRole('bob@e2e.test', 'team_lead');
await sleep(1000);
await shot('e5-bob-team-lead');

await logout();
await login('bob@e2e.test', 'Passw0rd!23');
await waitForText('Members', 30000);
let nav = await navLabels();
assert(nav.includes('Mine') && nav.includes('Tasks') && nav.includes('Planner'), 'Team lead tabs are wrong', nav);
assert(!nav.includes('Projects'), 'Team lead sees Projects', nav);
await shot('e5-team-lead-tabs');

// --- Viewer ---
await logout();
await login('admin@e2e.test', 'Passw0rd!23');
await waitForText('Projects', 30000);
await clickLabel('^Members$');
await waitForText('Bob', 20000);
await sleep(1000);
await changeRole('Bob', 'Viewer');
await waitApiRole('bob@e2e.test', 'viewer');
await sleep(1000);
await shot('e5-bob-viewer');

await logout();
await login('bob@e2e.test', 'Passw0rd!23');
await waitForText('Members', 30000);
nav = await navLabels();
assert(nav.includes('Mine') && nav.includes('Tasks'), 'Viewer tabs are wrong', nav);
assert(!nav.includes('Planner') && !nav.includes('Dashboard') && !nav.includes('Projects'), 'Viewer has extra tabs', nav);
await clickLabel('^Tasks$');
await sleep(1500);
let text = await pageText();
assert(!/Add task/.test(text), 'Viewer can see the Add task button', text);
await shot('e5-viewer-tasks');

// A viewer is read-only on the server too, not just in the UI.
const bobLogin = (await api('POST', '/auth/login', { email: 'bob@e2e.test', password: 'Passw0rd!23' })).json;
const alpha = (await api('GET', '/projects')).json.items.find((p) => p.name === 'Alpha');
const denied = await api('POST', '/tasks', { project_id: alpha.id, title: 'Viewer attempt', priority: 'low' }, bobLogin.access_token);
assert(denied.status === 403, 'A viewer could create a task through the API', denied);

// --- Admin ---
await logout();
await login('admin@e2e.test', 'Passw0rd!23');
await waitForText('Projects', 30000);
await clickLabel('^Members$');
await waitForText('Bob', 20000);
await sleep(1000);
await changeRole('Bob', 'Admin');
await waitForText('Give admin access', 10000);
await shot('e5-confirm-admin');
await clickText('^Make admin$');
await waitApiRole('bob@e2e.test', 'admin');
await sleep(1500);

await logout();
await login('bob@e2e.test', 'Passw0rd!23');
await waitForText('Projects', 30000);
nav = await navLabels();
assert(nav.includes('Projects') && nav.includes('Members'), 'Admin Bob tabs are wrong', nav);
assert(!nav.includes('Mine'), 'Admin Bob should not see Mine', nav);
await shot('e5-bob-admin-tabs');

// --- Back to user ---
await logout();
await login('admin@e2e.test', 'Passw0rd!23');
await waitForText('Projects', 30000);
await clickLabel('^Members$');
await waitForText('Bob', 20000);
await sleep(1000);
await changeRole('Bob', 'User');
await waitApiRole('bob@e2e.test', 'user');
await sleep(1000);
await shot('e5-bob-user');

console.log('E5 PASSED: admin changed Bob through team lead, viewer, admin and user; tabs follow the role and a viewer is read-only (UI + API 403).');
process.exit(0);

