import { connect } from './cdp.mjs';

const API = 'http://localhost:8000/api/v1';
const { send } = await connect();
void send;

function assert(condition, message, detail = '') {
  if (!condition) throw new Error(`${message}\n${String(detail).slice(0, 2000)}`);
}

async function api(method, path, body, token) {
  const response = await fetch(`${API}${path}`, {
    method,
    headers: {
      'Content-Type': 'application/json',
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
    },
    body: body ? JSON.stringify(body) : undefined,
  });
  const text = await response.text();
  let json = null;
  try { json = text ? JSON.parse(text) : null; } catch { json = text; }
  return { status: response.status, json };
}

async function login(email) {
  const response = await api('POST', '/auth/login', { email, password: 'Passw0rd!23' });
  assert(response.status === 200, `${email} login failed`, response);
  return response.json;
}

const admin = await login('admin@e2e.test');
const bruno = await login('bruno@e2e.test');

const projects = (await api('GET', '/projects')).json.items;
const alpha = projects.find((p) => p.name === 'Alpha');
const beta = projects.find((p) => p.name === 'Beta');
assert(alpha && beta, 'Alpha/Beta missing', projects);

const alphaTasks = (await api('GET', `/tasks?project_id=${alpha.id}&limit=100`, null, admin.access_token)).json.items;
assert(alphaTasks.length > 0, 'No Alpha task to protect');
const alphaTask = alphaTasks[0];

const alphaMembers = (await api('GET', '/members?limit=100', null, admin.access_token)).json.items;
const alice = alphaMembers.find((m) => m.email === 'alice@e2e.test');
const carol = alphaMembers.find((m) => m.email === 'carol@e2e.test');

const attempts = [
  ['GET', `/tasks?project_id=${alpha.id}`],
  ['POST', '/tasks', { project_id: alpha.id, title: 'Bruno intrusion', priority: 'low' }],
  ['PATCH', `/tasks/${alphaTask.id}`, { title: 'Bruno renaming Alpha' }],
  ['PATCH', `/tasks/${alphaTask.id}/complete`],
  ['PATCH', `/tasks/${alphaTask.id}/reopen`],
  ['DELETE', `/tasks/${alphaTask.id}`],
  ['POST', '/tasks/bulk/complete', { task_ids: [alphaTask.id] }],
  ['POST', '/tasks/bulk/reassign', { task_ids: [alphaTask.id], assignee_id: null }],
  ['POST', '/tasks/bulk/delete', { task_ids: [alphaTask.id] }],
  ['GET', `/tasks/${alphaTask.id}/subtasks`],
  ['POST', `/tasks/${alphaTask.id}/subtasks`, { title: 'Bruno subtask' }],
  ['GET', `/analytics/dashboard?project_id=${alpha.id}`],
  ['POST', `/projects/${alpha.id}/assign-owner`, { owner_id: bruno.account.id }],
  ['PATCH', `/projects/${alpha.id}/archive`],
  ['PATCH', `/projects/${alpha.id}/restore`],
  ['POST', '/members', {
    name: 'Intruder', email: 'intruder@e2e.test', password: 'Passw0rd!23',
    position: 'Nope', project_id: alpha.id, role: 'user',
  }],
  ['POST', `/members/${alice.id}/role`, { role: 'viewer' }],
  ['POST', `/members/${carol.id}/confirm`],
];

const results = [];
for (const [method, path, body] of attempts) {
  const response = await api(method, path, body, bruno.access_token);
  results.push(`${method} ${path} -> ${response.status}`);
  assert(response.status === 403, `Expected 403 for ${method} ${path}`, response);
}

// No cross-project data leaks in the lists.
const brunoTasks = (await api('GET', '/tasks?limit=100', null, bruno.access_token)).json;
assert(brunoTasks.status === undefined, 'Unexpected task list shape', brunoTasks);
assert(
  brunoTasks.items.every((task) => task.project_id === beta.id),
  'Bruno sees tasks from another project',
  brunoTasks.items.map((t) => [t.id, t.project_id, t.title]),
);
const brunoMembers = (await api('GET', '/members?limit=100', null, bruno.access_token)).json;
assert(
  brunoMembers.items.every((m) => m.project_id === beta.id),
  'Bruno sees members from another project',
  brunoMembers.items.map((m) => [m.id, m.project_id, m.email]),
);
assert(!brunoMembers.items.some((m) => m.email === 'alice@e2e.test'), 'Bruno sees Alice', brunoMembers.items);

// The protected task is untouched.
const after = (await api('GET', `/tasks?project_id=${alpha.id}&limit=100`, null, admin.access_token)).json.items;
const same = after.find((task) => task.id === alphaTask.id);
assert(same && same.title === alphaTask.title && same.status === alphaTask.status, 'Alpha task was modified', same);

// Anonymous access is rejected as well.
const anonymous = await api('GET', '/tasks');
assert(anonymous.status === 401, 'Anonymous task list is not 401', anonymous);

console.log('E6 PASSED: 18 cross-project attempts returned 403, lists are scoped to Beta, and the Alpha task is unchanged.');
console.log(results.join('\n'));
process.exit(0);

