const bulkAttempts = [
  ['/tasks/bulk/complete', { task_ids: [alphaTask.id] }],
  ['/tasks/bulk/reassign', { task_ids: [alphaTask.id], assignee_id: null }],
  ['/tasks/bulk/delete', { task_ids: [alphaTask.id] }],
];
