import { clickAt, connect, evaluate, sleep } from './cdp.mjs';
import { clickLabel, login, pageText, shot, waitForText } from './lib.mjs';

const { send } = await connect();

function assert(condition, message, detail = '') {
  if (!condition) throw new Error(`${message}\n${String(detail).slice(0, 2000)}`);
}

async function reload() {
  await send('Page.enable');
  await send('Page.reload');
  await sleep(4500);
  for (let i = 0; i < 40; i += 1) {
    const ready = await evaluate(send, `!!document.querySelector('flt-semantics-placeholder')`);
    if (ready) {
      await evaluate(send, `document.querySelector('flt-semantics-placeholder').click()`);
      break;
    }
    await sleep(500);
  }
  await sleep(1500);
}

async function storedToken() {
  return evaluate(send, `localStorage.getItem('flutter.session_token')`);
}

async function logout() {
  const avatar = await evaluate(send, `(() => {
    for (const el of document.querySelectorAll('flt-semantics[flt-tappable]')) {
      const label = el.getAttribute('aria-label') || '';
      const r = el.getBoundingClientRect();
      if (r.y < 60 && r.x > 900 && r.width > 20 && !/Notifications|Theme/.test(label)) {
        return { x: r.x + r.width / 2, y: r.y + r.height / 2 };
      }
    }
    return null;
  })()`);
  assert(avatar, 'Avatar not found');
  await clickAt(send, avatar.x, avatar.y);
  await sleep(900);
  await clickLabel('^Log out$');
  await waitForText('Log in', 20000);
  await sleep(800);
}

assert((await storedToken()) !== null, 'No stored token before the test');

// --- 1. Tampered token: restore rejects it and the login page explains why ---
await evaluate(send, `localStorage.setItem('flutter.session_token', JSON.stringify('tampered.token.value'))`);
await reload();
await waitForText('Log in', 40000);
let text = await pageText();
assert(/Your session expired\. Log in again\./.test(text), 'Expired-session notice missing', text);
assert(!/Projects/.test(text), 'Home content visible with a tampered token', text);
await shot('e8-tampered-token');
assert((await storedToken()) === null, 'Tampered token was not removed from storage');

// --- 2. A fresh login works and persists across a reload ---
await login('admin@e2e.test', 'Passw0rd!23');
await waitForText('Projects', 30000);
assert((await storedToken()) !== null, 'Login did not persist the token');
await reload();
await waitForText('Projects', 40000);
text = await pageText();
assert(/Admin E2E/.test(text), 'Session was not restored after reload', text);
await shot('e8-session-restored');

// --- 3. Logout clears the token and the router stays on /login ---
await logout();
text = await pageText();
assert(/Log in/.test(text) && !/Projects/.test(text), 'Logout did not return to login', text);
assert((await storedToken()) === null, 'Logout left the token in storage');
await shot('e8-logged-out');

// --- 4. Reload after logout: no residual access ---
await reload();
await sleep(1500);
text = await pageText();
const url = await evaluate(send, `location.href`);
assert(/#\/login$/.test(url), `Reload after logout is not on /login: ${url}`, text);
assert(!/Projects/.test(text), 'Reload after logout shows home content', text);

// --- 5. Direct navigation to /home is redirected ---
await evaluate(send, `location.hash = '#/home'`);
await sleep(2000);
text = await pageText();
const url2 = await evaluate(send, `location.href`);
assert(/#\/login$/.test(url2), `Direct /home was not redirected: ${url2}`, text);
await shot('e8-home-blocked');

console.log('E8 PASSED: invalid token shows the expired notice, logout clears the session, reload and direct /home stay blocked.');
process.exit(0);

