import { clickAt, connect, evaluate, sleep } from './cdp.mjs';
import { clickLabel, clickText, login, pageText, shot, waitForText } from './lib.mjs';

const API = 'http://localhost:8000/api/v1';
const { send } = await connect();

function assert(condition, message, detail = '') {
  if (!condition) throw new Error(`${message}\n${String(detail).slice(0, 2000)}`);
}

async function api(method, path, body, token) {
  const response = await fetch(`${API}${path}`, {
    method,
    headers: {
      'Content-Type': 'application/json',
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
    },
    body: body ? JSON.stringify(body) : undefined,
  });
  const text = await response.text();
  let json = null;
  try { json = text ? JSON.parse(text) : null; } catch { json = text; }
  return { status: response.status, json };
}

async function loginApi(email) {
  const response = await api('POST', '/auth/login', { email, password: 'Passw0rd!23' });
  assert(response.status === 200, `${email} API login failed`, response);
  return response.json;
}

async function logout() {
  const avatar = await evaluate(send, `(() => {
    for (const el of document.querySelectorAll('flt-semantics[flt-tappable]')) {
      const label = el.getAttribute('aria-label') || '';
      const r = el.getBoundingClientRect();
      if (r.y < 60 && r.x > 900 && r.width > 20 && !/Notifications|Theme/.test(label)) {
        return { x: r.x + r.width / 2, y: r.y + r.height / 2 };
      }
    }
    return null;
  })()`);
  assert(avatar, 'Avatar not found');
  await clickAt(send, avatar.x, avatar.y);
  await sleep(900);
  await clickLabel('^Log out$');
  await waitForText('Log in', 20000);
  await sleep(700);
}

const admin = await loginApi('admin@e2e.test');
const bob = await loginApi('bob@e2e.test');
const alice = await loginApi('alice@e2e.test');
const carol = await loginApi('carol@e2e.test');
const alpha = (await api('GET', '/projects')).json.items.find((p) => p.name === 'Alpha');
const bobMember = (await api('GET', '/members?limit=100', null, admin.access_token)).json.items
  .find((m) => m.email === 'bob@e2e.test');

const title = `E10 notification ${Date.now()}`;
const created = await api('POST', '/tasks', {
  project_id: alpha.id, title, priority: 'medium', assignee_id: bobMember.id,
}, admin.access_token);
assert(created.status === 201, 'Cannot create the notification task', created);

const bobList = (await api('GET', '/notifications?limit=100', null, bob.access_token)).json;
assert(bobList.unread >= 1, 'Bob has no unread notification', bobList);
const target = bobList.items.find((n) => n.title === `New task assigned: ${title}`);
assert(target, 'Bob is missing the task_created notification', bobList.items.slice(0, 5));
assert(!target.read_at, 'The new notification is already read', target);
const unreadBefore = bobList.unread;

// --- UI: the bell lists the notification, tapping it marks it read ---
let current = await pageText();
if (/Projects|Members|Tasks|Planner|Dashboard/.test(current)) {
  await logout();
}
await login('bob@e2e.test', 'Passw0rd!23');
await waitForText('Members', 30000);
await clickText('^Notifications$');
await waitForText('Notifications', 20000);
await sleep(1200);
let text = await pageText();
assert(text.includes(title), 'Notification screen is missing the new notification', text);
await shot('e10-bob-notifications');

await clickText(title);
await sleep(1800);

const afterList = (await api('GET', '/notifications?limit=100', null, bob.access_token)).json;
assert(afterList.unread === unreadBefore - 1, `Unread count did not drop (${unreadBefore} -> ${afterList.unread})`, afterList.unread);
const afterTarget = afterList.items.find((n) => n.id === target.id);
assert(afterTarget && afterTarget.read_at, 'The tapped notification is still unread', afterTarget);
await shot('e10-bob-after-read');

// The unread-only filter no longer lists it.
await clickLabel('^Unread only$');
await sleep(1500);
text = await pageText();
assert(!text.includes(title), 'The read notification still appears in the unread filter', text);
await shot('e10-bob-unread-filter');

// --- Isolation: Alice and Carol never see Bob's notification ---
for (const [name, account] of [['Alice', alice], ['Carol', carol]]) {
  const list = (await api('GET', '/notifications?limit=100', null, account.access_token)).json;
  assert(
    !list.items.some((n) => n.id === target.id || n.title === target.title),
    `${name} can read Bob's notification`,
    list.items.map((n) => n.title),
  );
}

await logout();
await login('alice@e2e.test', 'Passw0rd!23');
await waitForText('Members', 30000);
await clickText('^Notifications$');
await waitForText('Notifications', 20000);
await sleep(1200);
text = await pageText();
assert(!text.includes(title), "Alice's bell shows Bob's notification", text);
await shot('e10-alice-notifications');

console.log('E10 PASSED: task_created notification listed, tap marks it read (unread count -1, filter updated), Alice/Carol see nothing.');
process.exit(0);

