import { clickAt, connect, evaluate, sleep } from './cdp.mjs';
import { clickLabel, clickText, login, pageText, shot, waitForText } from './lib.mjs';

const API = 'http://localhost:8000/api/v1';
const { send } = await connect();

function assert(condition, message, detail = '') {
  if (!condition) throw new Error(`${message}\n${String(detail).slice(0, 2000)}`);
}

async function api(method, path, body, token) {
  const response = await fetch(`${API}${path}`, {
    method,
    headers: {
      'Content-Type': 'application/json',
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
    },
    body: body ? JSON.stringify(body) : undefined,
  });
  const text = await response.text();
  let json = null;
  try { json = text ? JSON.parse(text) : null; } catch { json = text; }
  return { status: response.status, json };
}

async function loginApi(email) {
  const response = await api('POST', '/auth/login', { email, password: 'Passw0rd!23' });
  assert(response.status === 200, `${email} API login failed`, response);
  return response.json;
}

async function logout() {
  const hasBack = await evaluate(send, `[...document.querySelectorAll('flt-semantics[flt-tappable]')]
    .some((el) => (el.getAttribute('aria-label') || '') === 'Back' || el.textContent.trim() === 'Back')`);
  if (hasBack) {
    await clickText('^Back$');
    await sleep(1200);
  }
  const avatar = await evaluate(send, `(() => {
    let best = null;
    for (const el of document.querySelectorAll('flt-semantics[flt-tappable]')) {
      const r = el.getBoundingClientRect();
      if (r.y >= 60 || r.x <= 900 || r.width < 48) continue;
      if (!best || r.x > best.x) best = { x: r.x + r.width / 2, y: r.y + r.height / 2 };
    }
    return best;
  })()`);
  assert(avatar, 'Avatar not found');
  await clickAt(send, avatar.x, avatar.y);
  await sleep(1000);
  await clickLabel('^Log out$');
  await waitForText('Log in', 20000);
  await sleep(700);
}

async function closeDialog() {
  await send('Input.dispatchKeyEvent', { type: 'keyDown', key: 'Escape', code: 'Escape', windowsVirtualKeyCode: 27 });
  await send('Input.dispatchKeyEvent', { type: 'keyUp', key: 'Escape', code: 'Escape', windowsVirtualKeyCode: 27 });
  await sleep(800);
}

async function subtasksOf(taskId, token) {
  const response = await api('GET', `/tasks/${taskId}/subtasks`, null, token);
  assert(response.status === 200, 'Cannot read subtasks', response);
  return response.json.items;
}

const admin = await loginApi('admin@e2e.test');
const alice = await loginApi('alice@e2e.test');
const alpha = (await api('GET', '/projects')).json.items.find((p) => p.name === 'Alpha');
const tasks = (await api('GET', `/tasks?project_id=${alpha.id}&limit=100`, null, alice.access_token)).json.items;
const target = tasks.find((t) => t.title === 'Bob review');
assert(target, 'Bob review task missing', tasks.map((t) => t.title));

// Clean slate (repeatable runs).
for (const sub of await subtasksOf(target.id, alice.access_token)) {
  await api('DELETE', `/tasks/subtasks/${sub.id}`, null, alpha ? alice.access_token : '');
}

// --- UI: add a subtask inside the task dialog ---
let text = await pageText();
if (/Edit task|New task/.test(text)) {
  await closeDialog();
  text = await pageText();
}
if (!/Log in/.test(text)) {
  await logout();
}
await login('alice@e2e.test', 'Passw0rd!23');
await waitForText('Members', 30000);
await clickLabel('^Tasks$');
await waitForText('Bob review', 20000);
await sleep(1000);
await clickLabel('^Bob review');
await waitForText('Edit task', 15000);
await sleep(800);
await shot('e11-edit-dialog');

await clickAt(send, 450, 462);
await sleep(500);
const inputReady = await evaluate(send, `!!document.querySelector('input[aria-label="Add subtask"]')`);
assert(inputReady, 'Add subtask field did not focus');
await send('Input.insertText', { text: 'Check specs' });
await sleep(400);
await clickText('^Add$');
await sleep(1000);
text = await pageText();
assert(/Check specs/.test(text), 'The new subtask is not listed in the dialog', text);
await shot('e11-subtask-added');

await clickText('^Save$');
await sleep(2000);
let subs = await subtasksOf(target.id, alice.access_token);
assert(subs.length === 1 && subs[0].title === 'Check specs' && subs[0].completed === false, 'Created subtask is wrong', subs);

// --- UI: tick the subtask ---
await clickLabel('^Bob review');
await waitForText('Check specs', 15000);
await sleep(800);
const toggle = await evaluate(send, `(() => {
  const title = [...document.querySelectorAll('flt-semantics')].find((el) => el.textContent.trim() === 'Check specs');
  if (!title) return null;
  const t = title.getBoundingClientRect();
  let best = null;
  for (const el of document.querySelectorAll('flt-semantics[role="checkbox"]')) {
    const r = el.getBoundingClientRect();
    const cy = r.y + r.height / 2;
    if (cy < t.y - 16 || cy > t.y + t.height + 16) continue;
    const area = r.width * r.height;
    if (!best || area < best.area) best = { x: r.x + r.width / 2, y: cy, area };
  }
  return best;
})()`);
assert(toggle, 'Subtask checkbox not found');
await clickAt(send, toggle.x, toggle.y);
await sleep(600);
await clickText('^Save$');
await sleep(2000);
subs = await subtasksOf(target.id, alice.access_token);
assert(subs.length === 1 && subs[0].completed === true, 'The subtask was not completed', subs);
await shot('e11-subtask-completed');

// --- UI: delete the subtask ---
await clickLabel('^Bob review');
await waitForText('Check specs', 15000);
await sleep(800);
const remove = await evaluate(send, `(() => {
  const title = [...document.querySelectorAll('flt-semantics')].find((el) => el.textContent.trim() === 'Check specs');
  if (!title) return null;
  const t = title.getBoundingClientRect();
  let best = null;
  for (const el of document.querySelectorAll('flt-semantics[flt-tappable]')) {
    const r = el.getBoundingClientRect();
    const cy = r.y + r.height / 2;
    if (cy < t.y - 16 || cy > t.y + t.height + 16) continue;
    if (r.x + r.width / 2 < t.x + 40) continue;
    const area = r.width * r.height;
    if (!best || area < best.area) best = { x: r.x + r.width / 2, y: cy, area };
  }
  return best;
})()`);
assert(remove, 'Subtask remove button not found');
await clickAt(send, remove.x, remove.y);
await sleep(600);
await clickText('^Save$');
await sleep(2000);
subs = await subtasksOf(target.id, alice.access_token);
assert(subs.length === 0, 'The subtask was not deleted', subs);

// --- Viewer: 403 on every subtask mutation ---
const bobId = (await api('GET', '/members?limit=100', null, admin.access_token)).json.items
  .find((m) => m.email === 'bob@e2e.test').id;
const toViewer = await api('POST', `/members/${bobId}/role`, { role: 'viewer' }, admin.access_token);
assert(toViewer.status === 200, 'Cannot temporarily set Bob to viewer', toViewer);
const bob = await loginApi('bob@e2e.test');

const adminSub = await api('POST', `/tasks/${target.id}/subtasks`, {
  task_id: target.id, title: 'Admin owned', sort_order: 0,
}, admin.access_token);
assert(adminSub.status === 201, 'Cannot create the admin subtask', adminSub);
const subId = adminSub.json.id;

const attempts = [
  ['POST', `/tasks/${target.id}/subtasks`, { task_id: target.id, title: 'Viewer attempt' }],
  ['PATCH', `/tasks/subtasks/${subId}`, { title: 'Viewer rename' }],
  ['DELETE', `/tasks/subtasks/${subId}`, null],
];
for (const [method, path, body] of attempts) {
  const response = await api(method, path, body, bob.access_token);
  assert(response.status === 403, `Expected 403 for viewer ${method} ${path}`, response);
}
const stillThere = await subtasksOf(target.id, alice.access_token);
assert(stillThere.length === 1 && stillThere[0].title === 'Admin owned', 'A viewer changed the subtask', stillThere);

await api('DELETE', `/tasks/subtasks/${subId}`, null, admin.access_token);
const toUser = await api('POST', `/members/${bobId}/role`, { role: 'user' }, admin.access_token);
assert(toUser.status === 200, 'Cannot restore Bob to user', toUser);

console.log('E11 PASSED: subtask add/tick/delete in the task dialog, persisted each time; a viewer gets 403 on create/update/delete.');
process.exit(0);

