import { clickAt, connect, evaluate, screenshot, sleep, typeText } from './cdp.mjs';
import { clickLabel, clickText } from './lib.mjs';

const { send } = await connect();
const shot = (n) => screenshot(send, `C:/Users/CHEDI/AppData/Local/Temp/opencode/e2e-run3/dbg-${n}.png`);

await clickLabel('^Bob review');
await sleep(2000);
await shot('1-open');
const geo = await evaluate(send, `(() => {
  const out = {};
  for (const el of document.querySelectorAll('flt-semantics')) {
    const t = el.textContent.trim();
    const l = el.getAttribute('aria-label') || '';
    if (['Add', 'Save', 'Cancel', 'Subtasks'].includes(t) || l === 'Add') {
      const r = el.getBoundingClientRect();
      out[t + '|' + l] = [r.x, r.y, r.width, r.height];
    }
  }
  return out;
})()`);
console.log('before', JSON.stringify(geo));

await clickAt(send, 450, 462);
await sleep(800);
await shot('2-focused');
const inputs = await evaluate(send, `[...document.querySelectorAll('input')].map(el => {
  const r = el.getBoundingClientRect();
  return { label: el.getAttribute('aria-label'), value: el.value, x: r.x, y: r.y, w: r.width, h: r.height };
})`);
console.log('inputs', JSON.stringify(inputs));
await typeText(send, 'Check specs');
await sleep(800);
await shot('3-typed');
console.log('dialog before add', /Edit task/.test(await evaluate(send, `document.body.innerText`)));

const add = await evaluate(send, `(() => {
  for (const el of document.querySelectorAll('flt-semantics')) {
    const t = el.textContent.trim();
    const l = el.getAttribute('aria-label') || '';
    if (t === 'Add' || l === 'Add') {
      const r = el.getBoundingClientRect();
      return { x: r.x + r.width / 2, y: r.y + r.height / 2, w: r.width, h: r.height, t, l };
    }
  }
  return null;
})()`);
console.log('add', JSON.stringify(add));
await clickAt(send, add.x, add.y);
await sleep(1200);
await shot('4-after-add');
const nodes = await evaluate(send, `[...document.querySelectorAll('flt-semantics')].map(el => el.textContent.trim()).filter(t => t).slice(0, 40)`);
console.log('after add nodes', JSON.stringify(nodes).slice(0, 1200));
process.exit(0);

