import { clickAt, connect, evaluate, sleep } from './cdp.mjs';
import { clickLabel, login, pageText, shot, waitForText } from './lib.mjs';

const API = 'http://localhost:8000/api/v1';
const { send } = await connect();

function assert(condition, message, detail = '') {
  if (!condition) throw new Error(`${message}\n${String(detail).slice(0, 2000)}`);
}

async function api(method, path, body, token) {
  const response = await fetch(`${API}${path}`, {
    method,
    headers: {
      'Content-Type': 'application/json',
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
    },
    body: body ? JSON.stringify(body) : undefined,
  });
  const text = await response.text();
  let json = null;
  try { json = text ? JSON.parse(text) : null; } catch { json = text; }
  return { status: response.status, json };
}

async function loginApi(email) {
  const response = await api('POST', '/auth/login', { email, password: 'Passw0rd!23' });
  assert(response.status === 200, `${email} API login failed`, response);
  return response.json;
}

async function logout() {
  const avatar = await evaluate(send, `(() => {
    let best = null;
    for (const el of document.querySelectorAll('flt-semantics[flt-tappable]')) {
      const r = el.getBoundingClientRect();
      if (r.y >= 60 || r.x <= 900 || r.width < 48) continue;
      if (!best || r.x > best.x) best = { x: r.x + r.width / 2, y: r.y + r.height / 2 };
    }
    return best;
  })()`);
  assert(avatar, 'Avatar not found');
  await clickAt(send, avatar.x, avatar.y);
  await sleep(1000);
  await clickLabel('^Log out$');
  await waitForText('Log in', 20000);
  await sleep(700);
}

/** Reads one KPI card: the numeric node sitting directly above its label. */
async function kpi(label) {
  return evaluate(send, `(() => {
    const nodes = [...document.querySelectorAll('flt-semantics')];
    const lab = nodes.find((el) => el.textContent.trim() === ${JSON.stringify(label)});
    if (!lab) return null;
    const lr = lab.getBoundingClientRect();
    for (const el of nodes) {
      const r = el.getBoundingClientRect();
      const t = el.textContent.trim();
      if (Math.abs(r.x - lr.x) > 2) continue;
      if (r.y >= lr.y || r.y < lr.y - 70) continue;
      if (/^\\d+(\\.\\d)?%?$/.test(t)) return t;
    }
    return null;
  })()`);
}

async function kpiSnapshot() {
  return {
    total: await kpi('Total'),
    completed: await kpi('Completed'),
    pending: await kpi('Pending'),
    overdue: await kpi('Overdue'),
    completion: await kpi('Completion'),
    velocity: await kpi('Velocity/wk'),
  };
}

function expected(stats) {
  return {
    total: String(stats.total_tasks),
    completed: String(stats.completed_tasks),
    pending: String(stats.pending_tasks),
    overdue: String(stats.overdue_tasks),
    completion: `${stats.completion_rate.toFixed(0)}%`,
    velocity: stats.velocity_per_week.toFixed(1),
  };
}

/** Opens the admin picker and selects the project at [index] (sorted by name). */
async function pickProject(index, expectedName) {
  const picker = await evaluate(send, `(() => {
    for (const el of document.querySelectorAll('flt-semantics[flt-tappable]')) {
      const r = el.getBoundingClientRect();
      const t = el.textContent.trim();
      if (r.y >= 60 && r.y < 120 && r.x > 700 && t && !/Refresh/.test(t)) {
        return { x: r.x + r.width / 2, y: r.y + r.height / 2, text: t };
      }
    }
    return null;
  })()`);
  assert(picker, 'Dashboard project picker not found');
  await clickAt(send, picker.x, picker.y);
  await sleep(1200);
  const press = async (key, code, vk) => {
    await send('Input.dispatchKeyEvent', { type: 'keyDown', key, code, windowsVirtualKeyCode: vk });
    await send('Input.dispatchKeyEvent', { type: 'keyUp', key, code, windowsVirtualKeyCode: vk });
    await sleep(320);
  };
  for (let i = 0; i < index; i += 1) {
    await press('ArrowDown', 'ArrowDown', 40);
  }
  await press('Enter', 'Enter', 13);
  await sleep(2500);
  const text = await pageText();
  assert(text.includes(expectedName), `Picker did not switch to ${expectedName}`, text.slice(0, 600));
}

// --- Fixtures -------------------------------------------------------------
const admin = await loginApi('admin@e2e.test');
const alice = await loginApi('alice@e2e.test');
const bob = await loginApi('bob@e2e.test');

const projects = (await api('GET', '/projects?limit=100')).json.items;
const alpha = projects.find((p) => p.name === 'Alpha');
const beta = projects.find((p) => p.name === 'Beta');
assert(alpha && beta, 'Alpha/Beta missing', projects);

const emptyName = `Empty E12 ${Date.now()}`;
const created = await api('POST', '/projects', { name: emptyName }, admin.access_token);
assert(created.status === 201, 'Cannot create the empty project', created);
const empty = created.json;

const alphaStats = (await api('GET', `/analytics/dashboard?project_id=${alpha.id}`, null, alice.access_token)).json;
const betaStats = (await api('GET', `/analytics/dashboard?project_id=${beta.id}`, null, admin.access_token)).json;
const emptyStats = (await api('GET', `/analytics/dashboard?project_id=${empty.id}`, null, admin.access_token)).json;
const allProjects = (await api('GET', '/projects?limit=100')).json.items
  .map((p) => p.name)
  .sort((a, b) => a.localeCompare(b));
const emptyIndex = allProjects.indexOf(emptyName);
assert(emptyIndex >= 0, 'Empty project missing from the picker list', allProjects);

// The API itself is isolated: Alice and Bob are Alpha-only.
const aliceBeta = await api('GET', `/analytics/dashboard?project_id=${beta.id}`, null, alice.access_token);
assert(aliceBeta.status === 403, 'Alice can read Beta analytics', aliceBeta);
const bobBeta = await api('GET', `/analytics/dashboard?project_id=${beta.id}`, null, bob.access_token);
assert(bobBeta.status === 403, 'Bob can read Beta analytics', bobBeta);
assert(betaStats.total_tasks !== alphaStats.total_tasks, 'Alpha and Beta metrics are identical (weak fixture)', { alphaStats, betaStats });

// An empty project is stable: zeros and no activity.
assert(emptyStats.total_tasks === 0 && emptyStats.completed_tasks === 0, 'Empty project is not empty', emptyStats);
assert(emptyStats.completion_rate === 0 && emptyStats.velocity_per_week === 0, 'Empty rates are not zero', emptyStats);
assert(Array.isArray(emptyStats.recent_events) && emptyStats.recent_events.length === 0, 'Empty project has events', emptyStats);

// --- Alice: dashboard matches the API, no picker, no Beta ---------------
let text = await pageText();
if (/Log in/.test(text)) {
  await login('alice@e2e.test', 'Passw0rd!23');
  await waitForText('Members', 30000);
} else {
  await logout();
  await login('alice@e2e.test', 'Passw0rd!23');
  await waitForText('Members', 30000);
}
await clickLabel('^Dashboard$');
await waitForText('Project Dashboard', 20000);
await sleep(1500);

const ui = await kpiSnapshot();
assert(JSON.stringify(ui) === JSON.stringify(expected(alphaStats)), 'Alpha KPI cards do not match the API', { ui, api: expected(alphaStats) });
text = await pageText();
assert(text.includes(`High: ${alphaStats.priority_mix.high}`), 'Priority legend (high) is wrong', text.slice(0, 900));
assert(text.includes(`Medium: ${alphaStats.priority_mix.medium}`), 'Priority legend (medium) is wrong');
assert(text.includes(`Low: ${alphaStats.priority_mix.low}`), 'Priority legend (low) is wrong');
const pickerForOwner = await evaluate(send, `[...document.querySelectorAll('flt-semantics[flt-tappable]')]
  .filter((el) => { const r = el.getBoundingClientRect(); return r.y >= 60 && r.y < 120 && r.x > 700; })
  .map((el) => el.textContent.trim())`);
assert(!pickerForOwner.some((t) => t === 'Alpha' || t === 'Beta'), 'A non-admin sees the project picker', pickerForOwner);
assert(!/Beta/.test(text), 'Alice sees Beta data on her dashboard', text.slice(0, 900));
await shot('e12-alice-dashboard');

// --- Admin: default project then the empty project ----------------------
await logout();
await login('admin@e2e.test', 'Passw0rd!23');
await waitForText('Projects', 30000);
await clickLabel('^Dashboard$');
await waitForText('Project Dashboard', 20000);
await sleep(1800);
// Defaults to the first project instead of "No project assigned.".
text = await pageText();
assert(!/No project assigned/.test(text), 'Admin dashboard has no default project', text.slice(0, 400));
const defaultKpis = await kpiSnapshot();
assert(defaultKpis.total !== null, 'Default dashboard did not load KPI cards');
const alphaName = alpha.name;
assert((await evaluate(send, `(() => {
  for (const el of document.querySelectorAll('flt-semantics[flt-tappable]')) {
    const r = el.getBoundingClientRect();
    if (r.y >= 60 && r.y < 120 && r.x > 700) return el.textContent.trim();
  }
  return null;
})()`)) === alphaName, 'Admin picker does not show the project on screen');
await shot('e12-admin-default');

await pickProject(emptyIndex, emptyName);
const emptyKpis = await kpiSnapshot();
assert(JSON.stringify(emptyKpis) === JSON.stringify(expected(emptyStats)), 'Empty project KPI cards are wrong', { emptyKpis, api: expected(emptyStats) });
text = await pageText();
assert(/No recent activity/.test(text), 'Empty project does not show the empty activity state', text.slice(0, 900));
assert(!/Could not load dashboard/.test(text), 'Empty project dashboard errors', text.slice(0, 900));
await shot('e12-empty-project');

// The picker now reflects the selection (not always the first project).
