import { clickAt, connect, evaluate, sleep } from './cdp.mjs';
import { clickLabel, clickText, login, pageText, shot, waitForText } from './lib.mjs';

const API = 'http://localhost:8000/api/v1';
const { send } = await connect();

function assert(condition, message, detail = '') {
  if (!condition) throw new Error(`${message}\n${String(detail).slice(0, 2000)}`);
}

async function api(method, path, body, token) {
  const response = await fetch(`${API}${path}`, {
    method,
    headers: {
      'Content-Type': 'application/json',
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
    },
    body: body ? JSON.stringify(body) : undefined,
  });
  const text = await response.text();
  let json = null;
  try { json = text ? JSON.parse(text) : null; } catch { json = text; }
  return { status: response.status, json };
}

async function loginApi(email) {
  const response = await api('POST', '/auth/login', { email, password: 'Passw0rd!23' });
  assert(response.status === 200, `${email} API login failed`, response);
  return response.json;
}

async function logout() {
  const avatar = await evaluate(send, `(() => {
    let best = null;
    for (const el of document.querySelectorAll('flt-semantics[flt-tappable]')) {
      const r = el.getBoundingClientRect();
      if (r.y >= 60 || r.x <= 900 || r.width < 48) continue;
      if (!best || r.x > best.x) best = { x: r.x + r.width / 2, y: r.y + r.height / 2 };
    }
    return best;
  })()`);
  assert(avatar, 'Avatar not found');
  await clickAt(send, avatar.x, avatar.y);
  await sleep(1000);
  await clickLabel('^Log out$');
  await waitForText('Log in', 20000);
  await sleep(700);
}

async function until(check, message, timeoutMs = 20000) {
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    if (await check()) return;
    await sleep(400);
  }
  throw new Error(message);
}

async function hasCard(name) {
  return evaluate(send, `[...document.querySelectorAll('flt-semantics[role="group"]')]
    .some((el) => (el.getAttribute('aria-label') || '').startsWith(${JSON.stringify(name + '\n')}))`);
}

/** Clicks a button (Archive/Restore) inside the card whose aria-label starts with [name]. */
async function cardButton(name, label) {
  const point = await evaluate(send, `(() => {
    const group = [...document.querySelectorAll('flt-semantics[role="group"]')]
      .find((el) => (el.getAttribute('aria-label') || '').startsWith(${JSON.stringify(name + '\n')}));
    if (!group) return null;
    const g = group.getBoundingClientRect();
    let best = null;
    for (const el of document.querySelectorAll('flt-semantics[flt-tappable]')) {
      if (el.textContent.trim() !== ${JSON.stringify(label)}) continue;
      const r = el.getBoundingClientRect();
      if (r.y < g.y - 2 || r.y + r.height > g.y + g.height + 2) continue;
      if (!best || r.width * r.height < best.area) {
        best = { x: r.x + r.width / 2, y: r.y + r.height / 2, area: r.width * r.height };
      }
    }
    return best;
  })()`);
  assert(point, `${label} button not found on the ${name} card`);
  await clickAt(send, point.x, point.y);
  await sleep(1500);
}

async function navLabels() {
  return evaluate(send, `[...document.querySelectorAll('flt-semantics[role="tab"]')]
    .map((el) => el.getAttribute('aria-label') || '')`);
}

// --- Fixtures -------------------------------------------------------------
const admin = await loginApi('admin@e2e.test');
const alice = await loginApi('alice@e2e.test');
const bob = await loginApi('bob@e2e.test');
const bruno = await loginApi('bruno@e2e.test');
const projects = (await api('GET', '/projects?limit=100')).json.items;
const alpha = projects.find((p) => p.name === 'Alpha');
const beta = projects.find((p) => p.name === 'Beta');
assert(alpha && beta, 'Alpha/Beta missing', projects);
assert(beta.status === 'active', 'Beta is not active before the test', beta);

const betaTasksBefore = (await api('GET', `/tasks?project_id=${beta.id}&limit=100`, null, admin.access_token)).json.items
  .map((t) => t.id).sort((a, b) => a - b);

// --- UI: archive Beta ------------------------------------------------------
let text = await pageText();
if (/Log in/.test(text)) {
  await login('admin@e2e.test', 'Passw0rd!23');
  await waitForText('Projects', 30000);
} else if (!/Projects/.test(text)) {
  await clickLabel('^Projects$');
  await sleep(1500);
}
await clickLabel('^Projects$');
await sleep(1800);
assert(await hasCard('Beta'), 'Beta card missing before archiving');

try {
  await cardButton('Beta', 'Archive');
  await waitForText('Project archived', 15000);
  text = await pageText();
  assert(!/Beta/.test(text), 'Beta is still listed after archiving', text.slice(0, 900));
  await shot('e13-beta-archived');
} catch (error) {
  // Leave the fixture usable even if the UI step fails.
  await api('PATCH', `/projects/${beta.id}/restore`, null, admin.access_token);
  throw error;
}

// The default API list (used by sign-up) hides Beta; the archived view exposes it.
const activeProjects = (await api('GET', '/projects?limit=100')).json.items;
assert(!activeProjects.some((p) => p.id === beta.id), 'Archived Beta is still in the default project list', activeProjects);
const allProjects = (await api('GET', '/projects?limit=100&include_archived=true')).json.items;
const archivedBeta = allProjects.find((p) => p.id === beta.id);
assert(archivedBeta && archivedBeta.status === 'archived', 'Beta is not archived in the API', archivedBeta);

// Beta's tasks are untouched by archiving.
const archivedTasks = (await api('GET', `/tasks?project_id=${beta.id}&limit=100`, null, admin.access_token)).json;
assert(archivedTasks.status === 200, 'Cannot read archived project tasks', archivedTasks);
assert(
  JSON.stringify(archivedTasks.items.map((t) => t.id).sort((a, b) => a - b)) === JSON.stringify(betaTasksBefore),
  'Archiving changed Beta tasks',
);

// --- UI: archived view and restore ----------------------------------------
await clickText('^Show archived$');
await waitForText('Archived Projects', 15000);
await until(() => hasCard('Beta'), 'Beta missing from the archived view');
text = await pageText();
assert(/archived/.test(text), 'The archived card does not show its status', text.slice(0, 900));
await shot('e13-archived-view');

await cardButton('Beta', 'Restore');
await waitForText('Project restored', 15000);
await until(async () => !(await hasCard('Beta')), 'Beta still in the archived view after restoring');
await shot('e13-after-restore');

const restored = (await api('GET', '/projects?limit=100&include_archived=true')).json.items
  .find((p) => p.id === beta.id);
assert(restored && restored.status === 'active', 'Beta was not restored in the API', restored);

await clickText('^Show active$');
await waitForText('Projects', 15000);
await until(() => hasCard('Beta'), 'Beta does not reappear in the active list');
await shot('e13-beta-back');

// --- RBAC: only an admin can archive or restore ---------------------------
const attempts = [
  ['Alice (owner)', alice, 'PATCH', `/projects/${alpha.id}/archive`],
  ['Alice (owner)', alice, 'PATCH', `/projects/${beta.id}/archive`],
  ['Bob (user)', bob, 'PATCH', `/projects/${alpha.id}/archive`],
  ['Bruno (Beta owner)', bruno, 'PATCH', `/projects/${beta.id}/archive`],
  ['Alice (owner)', alice, 'PATCH', `/projects/${beta.id}/restore`],
];
for (const [who, account, method, path] of attempts) {
  const response = await api(method, path, null, account.access_token);
  assert(response.status === 403, `${who} could call ${method} ${path}`, response);
}
const stillActive = (await api('GET', '/projects?limit=100')).json.items;
assert(stillActive.some((p) => p.id === beta.id), 'Beta was archived by a non-admin');

// Owners and users never see the Projects tab (and thus no archive control).
await logout();
await login('alice@e2e.test', 'Passw0rd!23');
await waitForText('Members', 30000);
let nav = await navLabels();
assert(!nav.includes('Projects'), 'Alice sees the Projects tab', nav);
await logout();
await login('bob@e2e.test', 'Passw0rd!23');
await waitForText('Members', 30000);
nav = await navLabels();
assert(!nav.includes('Projects'), 'Bob sees the Projects tab', nav);

// -------------------------------------------------------------------------
await logout();
await login('admin@e2e.test', 'Passw0rd!23');
await waitForText('Projects', 30000);

console.log('E13 PASSED: Beta hides when archived, appears in the archived view, restores, tasks survive, and only an admin can archive/restore.');
process.exit(0);

