import { clickAt, connect, evaluate, sleep } from './cdp.mjs';
import { clickLabel, clickText, login, pageText, shot, waitForText } from './lib.mjs';

const API = 'http://localhost:8000/api/v1';
const { send } = await connect();

function assert(condition, message, detail = '') {
  if (!condition) throw new Error(`${message}\n${String(detail).slice(0, 2000)}`);
}

async function api(method, path, body, token) {
  const response = await fetch(`${API}${path}`, {
    method,
    headers: {
      'Content-Type': 'application/json',
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
    },
    body: body ? JSON.stringify(body) : undefined,
  });
  const text = await response.text();
  let json = null;
  try { json = text ? JSON.parse(text) : null; } catch { json = text; }
  return { status: response.status, json };
}

async function loginApi(email) {
  const response = await api('POST', '/auth/login', { email, password: 'Passw0rd!23' });
  assert(response.status === 200, `${email} API login failed`, response);
  return response.json;
}

async function logout() {
  const avatar = await evaluate(send, `(() => {
    let best = null;
    for (const el of document.querySelectorAll('flt-semantics[flt-tappable]')) {
      const r = el.getBoundingClientRect();
      if (r.y >= 60 || r.x <= 900 || r.width < 48) continue;
      if (!best || r.x > best.x) best = { x: r.x + r.width / 2, y: r.y + r.height / 2 };
    }
    return best;
  })()`);
  assert(avatar, 'Avatar not found');
  await clickAt(send, avatar.x, avatar.y);
  await sleep(1000);
  await clickLabel('^Log out$');
  await waitForText('Log in', 20000);
  await sleep(700);
}

async function reloadPage() {
  await send('Page.enable');
  await send('Page.reload');
  await sleep(5000);
  for (let i = 0; i < 60; i += 1) {
    const ready = await evaluate(send, `!!document.querySelector('flt-semantics-placeholder')`);
    if (ready) {
      await evaluate(send, `document.querySelector('flt-semantics-placeholder').click()`);
      break;
    }
    await sleep(500);
  }
  await sleep(1500);
}

/** Centre of the tappable task card whose aria-label starts with [title]. */
async function cardPoint(title) {
  return evaluate(send, `(() => {
    const el = [...document.querySelectorAll('flt-semantics[role="group"][flt-tappable]')]
      .find((n) => (n.getAttribute('aria-label') || '').startsWith(${JSON.stringify(title + '\n')}));
    if (!el) return null;
    const r = el.getBoundingClientRect();
    if (!r.width || !r.height) return null;
    return { x: r.x + r.width / 2, y: r.y + r.height / 2 };
  })()`);
}

/** Scrolls the task list until the card is on screen. */
async function ensureCard(title) {
  for (let i = 0; i < 16; i += 1) {
    const point = await cardPoint(title);
    if (point && point.y > 250 && point.y < 470) return point;
    await send('Input.dispatchMouseEvent', {
      type: 'mouseWheel', x: 500, y: 360, deltaX: 0, deltaY: point ? -120 : 200,
    });
    await sleep(450);
  }
  throw new Error(`Task card ${title} never became visible`);
}

async function longPress(point) {
  await send('Input.dispatchMouseEvent', { type: 'mouseMoved', x: point.x, y: point.y });
  await send('Input.dispatchMouseEvent', { type: 'mousePressed', x: point.x, y: point.y, button: 'left', clickCount: 1 });
  await sleep(850);
  await send('Input.dispatchMouseEvent', { type: 'mouseReleased', x: point.x, y: point.y, button: 'left', clickCount: 1 });
  await sleep(1200);
}

async function selectThree(titles) {
  const first = await ensureCard(titles[0]);
  await longPress(first);
  let text = await pageText();
  assert(/1 selected/.test(text), 'Long-press did not enter multi-select', text.slice(0, 500));
  for (const title of titles.slice(1)) {
    const point = await ensureCard(title);
    await clickAt(send, point.x, point.y);
    await sleep(800);
  }
  text = await pageText();
  assert(/3 selected/.test(text), 'Three tasks are not selected', text.slice(0, 500));
}

async function selectAssignee(name, email) {
  const point = await evaluate(send, `(() => {
    for (const el of document.querySelectorAll('flt-semantics[flt-tappable]')) {
      const t = el.textContent.trim();
      if (t === ${JSON.stringify(`${name}\n${email}`)} || t === ${JSON.stringify(`${name} | ${email}`)}
          || (t.startsWith(${JSON.stringify(name + '\n')}) && t.includes(${JSON.stringify(email)}))) {
        const r = el.getBoundingClientRect();
        if (r.width && r.height) return { x: r.x + r.width / 2, y: r.y + r.height / 2 };
      }
    }
    return null;
  })()`);
  assert(point, `Assignee ${name} not found in the dialog`);
  await clickAt(send, point.x, point.y);
  await sleep(600);
}

async function taskByTitle(title, token) {
  const tasks = (await api('GET', `/tasks?project_id=${alpha.id}&limit=100`, null, token)).json.items;
  return tasks.find((t) => t.title === title);
}

// --- Fixtures -------------------------------------------------------------
const admin = await loginApi('admin@e2e.test');
const alice = await loginApi('alice@e2e.test');
const bruno = await loginApi('bruno@e2e.test');
const projects = (await api('GET', '/projects?limit=100')).json.items;
const alpha = projects.find((p) => p.name === 'Alpha');
assert(alpha, 'Alpha missing', projects);
const today = new Date().toISOString().slice(0, 10);
const stamp = Date.now();
const titlesA = [`E14 reassign ${stamp} A`, `E14 reassign ${stamp} B`, `E14 reassign ${stamp} C`];
const titlesB = [`E14 delete ${stamp} A`, `E14 delete ${stamp} B`, `E14 delete ${stamp} C`];

for (const title of [...titlesA, ...titlesB]) {
  const created = await api('POST', '/tasks', {
    project_id: alpha.id, title, priority: 'medium', due_date: today,
  }, alice.access_token);
  assert(created.status === 201, 'Cannot create the bulk fixture task', created);
}

const bobMember = (await api('GET', '/members?limit=100', null, admin.access_token)).json.items
  .find((m) => m.email === 'bob@e2e.test');
assert(bobMember, 'Bob is missing from the roster');

// --- UI: sign in as Alice and open Tasks --------------------------------
let text = await pageText();
if (/Log in/.test(text)) {
  await login('alice@e2e.test', 'Passw0rd!23');
} else {
  await logout();
  await login('alice@e2e.test', 'Passw0rd!23');
}
await waitForText('Members', 30000);
await reloadPage();
await waitForText('Alice', 30000);
await clickLabel('^Tasks$');
await waitForText(titlesA[0], 20000);
await sleep(1200);

// --- Bulk reassign --------------------------------------------------------
await selectThree(titlesA);
await shot('e14-selected');
await clickLabel('^Reassign selected$');
await waitForText('Reassign selected tasks', 15000);
await sleep(600);
await selectAssignee('Bob', 'bob@e2e.test');
await clickText('^Reassign$');
await waitForText('3 reassigned', 20000);
await sleep(1000);
for (const title of titlesA) {
  const task = await taskByTitle(title, admin.access_token);
  assert(task && task.assignee_id === bobMember.id, `${title} was not reassigned to Bob`, task);
}
await shot('e14-reassigned');

// --- Bulk complete --------------------------------------------------------
await selectThree(titlesA);
await clickLabel('^Complete selected$');
await waitForText('3 completed', 20000);
await sleep(1200);
for (const title of titlesA) {
  const task = await taskByTitle(title, admin.access_token);
  assert(task && task.status === 'completed', `${title} was not completed`, task);
}
await shot('e14-completed');

// --- Bulk delete ----------------------------------------------------------
await reloadPage();
await waitForText('Alice', 30000);
await clickLabel('^Tasks$');
await waitForText(titlesB[0], 20000);
await sleep(1200);
await selectThree(titlesB);
await clickLabel('^Delete selected$');
await waitForText('3 deleted', 20000);
await sleep(1200);
for (const title of titlesB) {
  assert(!(await taskByTitle(title, admin.access_token)), `${title} still exists after bulk delete`);
}
await shot('e14-deleted');

// --- Per-task results and cross-project refusal (API) ---------------------
const mixedTitle = `E14 mixed ${stamp}`;
const mixed = await api('POST', '/tasks', {
  project_id: alpha.id, title: mixedTitle, priority: 'low', due_date: today,
}, admin.access_token);
assert(mixed.status === 201, 'Cannot create the mixed-result task', mixed);
const mixedBulk = await api('POST', '/tasks/bulk/complete', {
  task_ids: [mixed.json.id, 999999],
}, admin.access_token);
assert(mixedBulk.status === 200, 'Mixed bulk call failed', mixedBulk);
assert(
  mixedBulk.json.succeeded === 1 && mixedBulk.json.failed === 1
  && mixedBulk.json.results.some((r) => r.task_id === mixed.json.id && r.success)
  && mixedBulk.json.results.some((r) => r.task_id === 999999 && r.success === false),
  'Bulk results are not per task',
  mixedBulk.json,
);

const protectedTitle = `E14 cross ${stamp}`;
const protectedTask = await api('POST', '/tasks', {
  project_id: alpha.id, title: protectedTitle, priority: 'low', due_date: today,
}, admin.access_token);
for (const [path, body] of [
  ['/tasks/bulk/complete', { task_ids: [protectedTask.json.id] }],
  ['/tasks/bulk/reassign', { task_ids: [protectedTask.json.id], assignee_id: bruno.account.id }],
  ['/tasks/bulk/delete', { task_ids: [protectedTask.json.id] }],
