3: /// Signals "server data changed" after a successful mutation so list streams
4: /// refetch. Services ping after writes; [watchFromApi] re-runs its fetch on
5: /// every ping, which keeps screens updating without provider rebuilds (and
6: /// therefore without loading-spinner flicker).
7: class DataSync {
8:   DataSync._();
9: 
10:   static final DataSync instance = DataSync._();
11: 
12:   final _changes = StreamController<void>.broadcast();
13: 
14:   Stream<void> get changes => _changes.stream;
15: 
16:   void ping() => _changes.add(null);
17: }
18: 
19: /// Emits [fetch]'s result immediately, then again after every [DataSync]
20: /// ping. A failed fetch errors the stream; screens recover through their
21: /// existing retry actions (provider invalidation resubscribes).
22: ///
23: /// Implemented with an explicit [StreamController] instead of an `async*`
24: /// generator: cancelling an `async*` stream that is waiting on a broadcast
25: /// stream never completes, which leaks subscriptions and hangs provider
26: /// disposal.
27: Stream<T> watchFromApi<T>(Future<T> Function() fetch) {
28:   late final StreamController<T> controller;
29:   StreamSubscription<void>? changes;
30:   var cancelled = false;
31:   var fetching = false;
32:   var queued = false;
33: 
34:   Future<void> refresh() async {
35:     if (fetching) {
36:       queued = true;
37:       return;
38:     }
39:     fetching = true;
40:     do {
41:       queued = false;
42:       try {
43:         final value = await fetch();
44:         if (!cancelled) {
45:           controller.add(value);
46:         }
47:       } catch (error, stackTrace) {
48:         if (!cancelled) {
49:           controller.addError(error, stackTrace);
50:         }
51:         queued = false;
52:       }
53:     } while (queued && !cancelled);
54:     fetching = false;
55:   }
56: 
57:   controller = StreamController<T>(
58:     onListen: () {
59:       changes = DataSync.instance.changes.listen((_) => refresh());
60:       refresh();
61:     },
62:     onCancel: () async {
63:       cancelled = true;
64:       await changes?.cancel();
65:       changes = null;
66:     },
67:   );
68:   return controller.stream;
