import { clickAt, connect, evaluate, sleep } from './cdp.mjs';
import { clickLabel, clickText, login, pageText, shot, waitForText } from './lib.mjs';

const API = 'http://localhost:8000/api/v1';
const { send } = await connect();

function assert(condition, message, detail = '') {
  if (!condition) throw new Error(`${message}\n${String(detail).slice(0, 2000)}`);
}

async function api(method, path, body, token) {
  const response = await fetch(`${API}${path}`, {
    method,
    headers: {
      'Content-Type': 'application/json',
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
    },
    body: body ? JSON.stringify(body) : undefined,
  });
  const text = await response.text();
  let json = null;
  try { json = text ? JSON.parse(text) : null; } catch { json = text; }
  return { status: response.status, json };
}

async function loginApi(email) {
  const response = await api('POST', '/auth/login', { email, password: 'Passw0rd!23' });
  assert(response.status === 200, `${email} API login failed`, response);
  return response.json;
}

async function logout() {
  const avatar = await evaluate(send, `(() => {
    let best = null;
    for (const el of document.querySelectorAll('flt-semantics[flt-tappable]')) {
      const r = el.getBoundingClientRect();
      if (r.y >= 60 || r.x <= 900 || r.width < 48) continue;
      if (!best || r.x > best.x) best = { x: r.x + r.width / 2, y: r.y + r.height / 2 };
    }
    return best;
  })()`);
  assert(avatar, 'Avatar not found');
  await clickAt(send, avatar.x, avatar.y);
  await sleep(1000);
  await clickLabel('^Log out$');
  await waitForText('Log in', 20000);
  await sleep(700);
}

async function reloadPage() {
  await send('Page.enable');
  await send('Page.reload');
  await sleep(5000);
  for (let i = 0; i < 60; i += 1) {
    const ready = await evaluate(send, `!!document.querySelector('flt-semantics-placeholder')`);
    if (ready) {
      await evaluate(send, `document.querySelector('flt-semantics-placeholder').click()`);
      break;
    }
    await sleep(500);
  }
  await sleep(1500);
}

async function navLabels() {
  return evaluate(send, `[...document.querySelectorAll('flt-semantics[role="tab"]')]
    .map((el) => el.getAttribute('aria-label') || '')`);
}

/** Types into the Members search box (x=400,y=88); the box is canvas-rendered. */
async function searchMember(value) {
  await clickAt(send, 400, 88);
  await sleep(400);
  let present = false;
  for (let i = 0; i < 25; i += 1) {
    present = await evaluate(send, `!!document.querySelector('input[placeholder="Search members"]')`);
    if (present) break;
    await sleep(120);
  }
  assert(present, 'Members search box did not expose its input');
  await send('Input.dispatchKeyEvent', {
    type: 'keyDown', key: 'a', code: 'KeyA', modifiers: 2, windowsVirtualKeyCode: 65,
  });
  await send('Input.dispatchKeyEvent', {
    type: 'keyUp', key: 'a', code: 'KeyA', modifiers: 2, windowsVirtualKeyCode: 65,
  });
  for (const char of value) {
    await send('Input.dispatchKeyEvent', { type: 'keyDown', text: char, key: char });
    await send('Input.dispatchKeyEvent', { type: 'keyUp', key: char });
    await sleep(40);
  }
  await sleep(1400);
  const actual = await evaluate(send, `document.querySelector('input[placeholder="Search members"]')?.value`);
  assert(actual === value, `Search box expected ${value}, got ${actual}`);
}

/** Clicks the "Change role" menu on the only card currently shown. */
async function openRoleMenu() {
  const button = await evaluate(send, `(() => {
    for (const el of document.querySelectorAll('flt-semantics[flt-tappable]')) {
      const label = (el.getAttribute('aria-label') || '').trim();
      const text = el.textContent.trim();
      if (label !== 'Change role' && text !== 'Change role') continue;
      const r = el.getBoundingClientRect();
      if (r.width && r.height) return { x: r.x + r.width / 2, y: r.y + r.height / 2 };
    }
    return null;
  })()`);
  assert(button, 'Change role button not found');
  await clickAt(send, button.x, button.y);
  await sleep(900);
}

async function visibleRoleButtons() {
  return evaluate(send, `[...document.querySelectorAll('flt-semantics[flt-tappable]')]
    .filter((el) => {
      const r = el.getBoundingClientRect();
      const label = (el.getAttribute('aria-label') || '').trim();
      const text = el.textContent.trim();
      return r.width && r.height && (label === 'Change role' || text === 'Change role');
    }).length`);
}

async function apiRole(email) {
  const admin = await loginApi('admin@e2e.test');
  const members = (await api('GET', '/members?limit=100', null, admin.access_token)).json.items;
  const member = members.find((m) => m.email === email);
  return member ? member.role : null;
}

async function waitApiRole(email, expected) {
  for (let i = 0; i < 40; i += 1) {
    if ((await apiRole(email)) === expected) return;
    await sleep(300);
  }
  throw new Error(`${email} role never became ${expected} (still ${await apiRole(email)})`);
}

async function changeRole(name, role) {
  await searchMember(name);
  assert((await visibleRoleButtons()) === 1, `Expected exactly one Change role button for ${name}`);
  await openRoleMenu();
  await clickLabel(`^${role}$`);
  await sleep(1000);
}

async function memberByEmail(email) {
  const admin = await loginApi('admin@e2e.test');
  const members = (await api('GET', '/members?limit=100', null, admin.access_token)).json.items;
  return members.find((m) => m.email === email);
}

// --- Fixtures -------------------------------------------------------------
const stamp = Date.now();
const pendingEmail = `dave.e15.${stamp}@e2e.test`;
const pendingName = `Dave E15 ${stamp}`;
const projects = (await api('GET', '/projects?limit=100')).json.items;
const alpha = projects.find((p) => p.name === 'Alpha');
const beta = projects.find((p) => p.name === 'Beta');
assert(alpha && beta, 'Alpha/Beta missing', projects);

const signup = await api('POST', '/auth/signup', {
  name: pendingName,
  email: pendingEmail,
  password: 'Passw0rd!23',
  position: 'QA',
  project_id: alpha.id,
});
assert(signup.status === 201, 'Cannot create the pending user', signup);
assert(signup.json.status === 'pending', 'The new user is not pending', signup.json);
const dave = signup.json;

// --- Admin promotes Bob to team lead through the UI -----------------------
let text = await pageText();
if (/Log in/.test(text)) {
  await login('admin@e2e.test', 'Passw0rd!23');
}
await waitForText('Projects', 30000);
await clickLabel('^Members$');
await waitForText('Bob', 20000);
await sleep(1200);
await changeRole('Bob', 'Team lead');
await waitApiRole('bob@e2e.test', 'team_lead');
await shot('e15-bob-team-lead');
const bob = await memberByEmail('bob@e2e.test');

// --- Team lead confirms the pending user --------------------------------
await logout();
await login('bob@e2e.test', 'Passw0rd!23');
await waitForText('Members', 30000);
let nav = await navLabels();
assert(nav.includes('Planner') && nav.includes('Dashboard'), 'Team lead tabs are wrong', nav);
assert(!nav.includes('Projects'), 'Team lead sees Projects', nav);
await sleep(1200);

await searchMember(pendingName);
text = await pageText();
assert(/Waiting for confirmation/.test(text), 'Team lead does not see the pending section', text.slice(0, 900));
assert(text.includes(pendingName), 'Team lead does not see the pending user', text.slice(0, 900));
assert(/Confirm/.test(text), 'Team lead has no Confirm button', text.slice(0, 900));
await shot('e15-pending-as-team-lead');
await clickText('^Confirm$');
await sleep(1800);

let confirmed = await memberByEmail(pendingEmail);
for (let i = 0; i < 30 && confirmed.status !== 'active'; i += 1) {
  await sleep(300);
  confirmed = await memberByEmail(pendingEmail);
}
assert(confirmed.status === 'active', 'The team lead did not confirm the user', confirmed);
assert(confirmed.approved_by === bob.id, 'approved_by is not the team lead', confirmed);
text = await pageText();
assert(!/Waiting for confirmation/.test(text), 'The pending section is still shown after confirming', text.slice(0, 900));
await shot('e15-confirmed');

// --- Team lead capability boundaries (API) -------------------------------
const bobLogin = await loginApi('bob@e2e.test');
const leadChecks = [
  ['create an admin', 'POST', '/members', {
    name: 'Escalation', email: `escalation.${stamp}@e2e.test`,
    password: 'Passw0rd!23', project_id: alpha.id, role: 'admin',
  }],
  ['create in another project', 'POST', '/members', {
    name: 'Cross Project', email: `cross.${stamp}@e2e.test`,
    password: 'Passw0rd!23', project_id: beta.id, role: 'user',
  }],
  ['change a role', 'POST', `/members/${dave.id}/role`, { role: 'viewer' }],
  ['create a project', 'POST', '/projects', { name: `Lead project ${stamp}` }],
  ['archive a project', 'PATCH', `/projects/${alpha.id}/archive`, null],
];
for (const [label, method, path, body] of leadChecks) {
  const response = await api(method, path, body, bobLogin.access_token);
  assert(response.status === 403, `A team lead could ${label}`, response);
}
// The confirmed account works: it can log in and sees Alpha only.
const daveLogin = await loginApi(pendingEmail);
assert(daveLogin.account.project_id === alpha.id, 'The confirmed user is not in Alpha', daveLogin.account);

// --- Admin changes Bob to viewer ----------------------------------------
// The change comes from another session, so Bob's app must refresh on reload.
const adminLogin = await loginApi('admin@e2e.test');
const demote = await api('POST', `/members/${bob.id}/role`, { role: 'viewer' }, adminLogin.access_token);
assert(demote.status === 200 && demote.json.role === 'viewer', 'Cannot demote Bob to viewer', demote);
await reloadPage();
await waitForText('Alice', 30000);

nav = await navLabels();
assert(
  nav.length === 3 && nav.includes('Members') && nav.includes('Tasks') && nav.includes('Mine'),
  'Viewer tabs are wrong',
  nav,
);
await clickLabel('^Tasks$');
await sleep(2000);
text = await pageText();
assert(!/Add task/.test(text), 'Viewer can see Add task', text.slice(0, 900));
await shot('e15-viewer-tasks');

await clickLabel('^Members$');
await sleep(1500);
text = await pageText();
assert(!/Add user/.test(text), 'Viewer can see Add user', text.slice(0, 900));
await searchMember(pendingName);
text = await pageText();
assert(!/Confirm/.test(text), 'Viewer sees a Confirm button', text.slice(0, 900));
await shot('e15-viewer-members');

// --- Viewer is read-only on the server -----------------------------------
// A throwaway task and subtask give PATCH/DELETE something to target; the
// viewer must be refused before anything is touched.
const taskResponse = await api('POST', '/tasks', {
  project_id: alpha.id, title: `E15 viewer guard ${stamp}`, priority: 'low',
}, adminLogin.access_token);
assert(taskResponse.status === 201, 'Cannot create the viewer-guard task', taskResponse);
const guardTask = taskResponse.json;
const subResponse = await api('POST', `/tasks/${guardTask.id}/subtasks`, {
  task_id: guardTask.id, title: 'Guard subtask', sort_order: 0,
}, adminLogin.access_token);
assert(subResponse.status === 200 || subResponse.status === 201, 'Cannot create the guard subtask', subResponse);
const guardSub = subResponse.json;

const viewerToken = await loginApi('bob@e2e.test');
const viewerChecks = [
  ['edit a task', 'PATCH', `/tasks/${guardTask.id}`, { title: 'Viewer edit' }],
  ['complete a task', 'PATCH', `/tasks/${guardTask.id}/complete`, null],
  ['reopen a task', 'PATCH', `/tasks/${guardTask.id}/reopen`, null],
  ['delete a task', 'DELETE', `/tasks/${guardTask.id}`, null],
  ['create a subtask', 'POST', `/tasks/${guardTask.id}/subtasks`, {
    task_id: guardTask.id, title: 'Viewer subtask', sort_order: 0,
  }],
  ['update a subtask', 'PATCH', `/tasks/subtasks/${guardSub.id}`, { completed: true }],
  ['delete a subtask', 'DELETE', `/tasks/subtasks/${guardSub.id}`, null],
  ['bulk complete', 'POST', '/tasks/bulk/complete', { task_ids: [guardTask.id] }],
  ['bulk reassign', 'POST', '/tasks/bulk/reassign', {
    task_ids: [guardTask.id], assignee_id: dave.id,
  }],
  ['bulk delete', 'POST', '/tasks/bulk/delete', { task_ids: [guardTask.id] }],
  ['create a member', 'POST', '/members', {
    name: 'Viewer member', email: `viewer.${stamp}@e2e.test`,
    password: 'Passw0rd!23', project_id: alpha.id, role: 'user',
  }],
  ['confirm a member', 'POST', `/members/${dave.id}/confirm`, null],
  ['change a role', 'POST', `/members/${dave.id}/role`, { role: 'viewer' }],
  ['archive a project', 'PATCH', `/projects/${alpha.id}/archive`, null],
];
for (const [label, method, path, body] of viewerChecks) {
  const response = await api(method, path, body, viewerToken.access_token);
  assert(response.status === 403, `A viewer could ${label}`, response);
