import 'dart:io';

import 'package:flutter/foundation.dart';
import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:task_planner/models/models.dart';

import 'support/app_harness.dart';

void main() {
  testWidgets('dump enlarged tasks overflow', (tester) async {
    tester.view.physicalSize = const Size(360, 640);
    tester.view.devicePixelRatio = 1;
    tester.platformDispatcher.textScaleFactorTestValue = 1.6;
    addTearDown(tester.view.reset);
    addTearDown(tester.platformDispatcher.clearTextScaleFactorTestValue);

    final errors = <FlutterErrorDetails>[];
    final original = FlutterError.onError;
    FlutterError.onError = errors.add;
    addTearDown(() => FlutterError.onError = original);

    final fixture = Fixture();
    fixture.api.addTask(
      Task(
        id: 1,
        title: 'A reasonably long task title that wraps on a narrow screen',
        description: 'With a description that also wraps.',
        projectId: fixture.project.id,
        dueDate: DateTime.now(),
        createdAt: DateTime.now(),
      ),
    );
    await pumpTaskPlanner(tester, fixture.api, account: fixture.owner);
    await tester.tap(find.byType(NavigationDestination).at(1));
    await settle(tester);

    for (final details in errors) {
      stdout.writeln('=== OVERFLOW DETAILS ===');
      stdout.writeln(details.toString());
    }
    errors.clear();
  });
}

