async function ensureCard(title) {
  for (let i = 0; i < 20; i += 1) {
    const point = await cardPoint(title);
    if (point && point.y > 260 && point.y < 460) return point;
    // Flutter web ignores wheel events at a position the pointer never
    // visited after a reload, so move the mouse there first. Cards that
    // exist but sit below the viewport must be scrolled down, not up.
    const delta = point && point.y <= 260 ? -160 : 220;
    await send('Input.dispatchMouseEvent', { type: 'mouseMoved', x: 500, y: 360 });
    await sleep(100);
    await send('Input.dispatchMouseEvent', {
      type: 'mouseWheel', x: 500, y: 360, deltaX: 0, deltaY: delta,
    });
    await sleep(450);
  }
  throw new Error(`Task card ${title} never became visible`);
}

