import fs from 'node:fs';
import { connect, evaluate, sleep } from './cdp.mjs';

const { send } = await connect();
const log = [];
const tabs = await evaluate(send, `(() => [...document.querySelectorAll('flt-semantics[role="tab"]')].map((el) => {
  const r = el.getBoundingClientRect();
  return { label: el.getAttribute('aria-label'), text: el.textContent.trim(), x: Math.round(r.x + r.width / 2), y: Math.round(r.y + r.height / 2) };
}))()`);
log.push('tabs ' + JSON.stringify(tabs));
const planner = tabs.find((t) => t.label === 'Planner');
if (planner) {
  await send('Input.dispatchMouseEvent', { type: 'mouseMoved', x: planner.x, y: planner.y });
  await send('Input.dispatchMouseEvent', { type: 'mousePressed', x: planner.x, y: planner.y, button: 'left', clickCount: 1 });
  await send('Input.dispatchMouseEvent', { type: 'mouseReleased', x: planner.x, y: planner.y, button: 'left', clickCount: 1 });
  await sleep(2500);
}
log.push('body ' + JSON.stringify(await evaluate(send, 'document.body.innerText.slice(0, 400)')));
fs.writeFileSync('dbg-planner-click.txt', log.join('\n'));
process.exit(0);

