import { clickAt, connect, evaluate, sleep } from './cdp.mjs';
import { clickLabel, clickText, fill, login, pageText, shot, waitForText } from './lib.mjs';

const API = 'http://localhost:8000/api/v1';
const { send } = await connect();

function assert(condition, message, detail = '') {
  if (!condition) throw new Error(`${message}\n${String(detail).slice(0, 2000)}`);
}

async function api(method, path, body, token) {
  const response = await fetch(`${API}${path}`, {
    method,
    headers: {
      'Content-Type': 'application/json',
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
    },
    body: body ? JSON.stringify(body) : undefined,
  });
  const text = await response.text();
  let json = null;
  try { json = text ? JSON.parse(text) : null; } catch { json = text; }
  return { status: response.status, json };
}

async function loginApi(email) {
  const response = await api('POST', '/auth/login', { email, password: 'Passw0rd!23' });
  assert(response.status === 200, `${email} API login failed`, response);
  return response.json;
}

async function logout() {
  const avatar = await evaluate(send, `(() => {
    let best = null;
    for (const el of document.querySelectorAll('flt-semantics[flt-tappable]')) {
      const r = el.getBoundingClientRect();
      if (r.y >= 60 || r.x <= 900 || r.width < 48) continue;
      if (!best || r.x > best.x) best = { x: r.x + r.width / 2, y: r.y + r.height / 2 };
    }
    return best;
  })()`);
  assert(avatar, 'Avatar not found');
  await clickAt(send, avatar.x, avatar.y);
  await sleep(1000);
  await clickLabel('^Log out$');
  await waitForText('Log in', 20000);
  await sleep(700);
}

async function reloadPage() {
  await send('Page.enable');
  await send('Page.reload');
  await sleep(5000);
  for (let i = 0; i < 60; i += 1) {
    const ready = await evaluate(send, `!!document.querySelector('flt-semantics-placeholder')`);
    if (ready) {
      await evaluate(send, `document.querySelector('flt-semantics-placeholder').click()`);
      break;
    }
    await sleep(500);
  }
  await sleep(1500);
}

/** Types into the Planner search box, whose hint is not exposed as text. */
async function searchPlanner(value) {
  await clickAt(send, 400, 78);
  await sleep(400);
  let present = false;
  for (let i = 0; i < 25; i += 1) {
    present = await evaluate(send, `!!document.querySelector('input[placeholder="Search tasks"]')`);
    if (present) break;
    await sleep(120);
  }
  assert(present, 'Planner search box did not expose its input');
  await send('Input.dispatchKeyEvent', {
    type: 'keyDown', key: 'a', code: 'KeyA', modifiers: 2, windowsVirtualKeyCode: 65,
  });
  await send('Input.dispatchKeyEvent', {
    type: 'keyUp', key: 'a', code: 'KeyA', modifiers: 2, windowsVirtualKeyCode: 65,
  });
  for (const char of value) {
    await send('Input.dispatchKeyEvent', { type: 'keyDown', text: char, key: char });
    await send('Input.dispatchKeyEvent', { type: 'keyUp', text: char, key: char });
    await sleep(40);
  }
  await sleep(1400);
  const actual = await evaluate(send, `document.querySelector('input[placeholder="Search tasks"]')?.value`);
  assert(actual === value, `Planner search expected ${value}, got ${actual}`);
}

/** Row centre and checkbox point for the task card with this title. */
async function rowPoints(title) {
  return evaluate(send, `(() => {
    const el = [...document.querySelectorAll('flt-semantics[role="group"]')]
      .find((n) => (n.getAttribute('aria-label') || '').startsWith(${JSON.stringify(title + '\n')}));
    if (!el) return null;
    const r = el.getBoundingClientRect();
    if (!r.width || !r.height) return null;
    return { checkboxX: r.x + 24, y: r.y + r.height / 2 };
  })()`);
}

async function taskByTitle(title, token) {
  const tasks = (await api('GET', `/tasks?project_id=${alphaId}&limit=100`, null, token)).json.items;
  return tasks.find((t) => t.title === title);
}

// --- Fixtures -------------------------------------------------------------
const stamp = Date.now();
const title = `E16 planner ${stamp}`;
const adminLogin = await loginApi('admin@e2e.test');
const projects = (await api('GET', '/projects?limit=100')).json.items;
const alpha = projects.find((p) => p.name === 'Alpha');
assert(alpha, 'Alpha missing', projects);
const alphaId = alpha.id;

// Remove fixtures left behind by earlier runs.
const existing = (await api('GET', `/tasks?project_id=${alphaId}&limit=100`, null, adminLogin.access_token)).json.items;
const stale = existing.filter((t) => t.title.startsWith('E16 planner ')).map((t) => t.id);
if (stale.length) {
  await api('POST', '/tasks/bulk/delete', { task_ids: stale }, adminLogin.access_token);
}

// --- UI: sign in as Alice and open Planner --------------------------------
await reloadPage();
const who = await evaluate(send, `(() => {
  for (const el of document.querySelectorAll('flt-semantics[flt-tappable]')) {
    const r = el.getBoundingClientRect();
    if (r.y < 60 && r.x > 900 && r.width >= 48) {
      return (el.textContent.trim() || el.getAttribute('aria-label') || '').split('\\n')[0];
    }
  }
  return null;
})()`);
if (!who) {
  await login('alice@e2e.test', 'Passw0rd!23');
} else if (who !== 'Alice') {
  await logout();
  await login('alice@e2e.test', 'Passw0rd!23');
}
await waitForText('Members', 30000);
await clickLabel('^Planner$');
await waitForText('Add task', 20000);
await sleep(1200);
const text = await pageText();
assert(/Overdue/.test(text), 'Planner has no overdue section', text.slice(0, 900));
assert(/Upcoming/.test(text), 'Planner has no upcoming section', text.slice(0, 900));
assert(/Add task/.test(text), 'Planner FAB is missing', text.slice(0, 900));
await shot('e16-planner-sections');

// --- Inline creation ------------------------------------------------------
await clickText('^Add task$');
await waitForText('Add Task', 15000);
await sleep(600);
await fill('Title *', title);
await sleep(400);
await clickText('^Add$');
await sleep(2500);

// Filter down to the new task so its section is always on screen.
await searchPlanner(title.toLowerCase());
await waitForText(title, 20000);
await sleep(1200);
const created = await taskByTitle(title, adminLogin.access_token);
assert(created && created.status === 'todo', 'The planner did not persist the new task', created);
const sectionText = await pageText();
assert(/No due date/.test(sectionText), 'The new undated task is not in "No due date"', sectionText.slice(0, 900));
await shot('e16-planner-created');

// --- Inline completion ----------------------------------------------------
let point = null;
for (let i = 0; i < 20 && !point; i += 1) {
  point = await rowPoints(title);
  if (!point) await sleep(300);
}
assert(point, 'The planner task row was not found');
await clickAt(send, point.checkboxX, point.y);
let completed = created;
for (let i = 0; i < 30 && completed.status !== 'completed'; i += 1) {
  await sleep(300);
  completed = await taskByTitle(title, adminLogin.access_token);
}
assert(completed && completed.status === 'completed', 'The planner checkbox did not complete the task', completed);
await waitForText('Completed', 15000);
await shot('e16-planner-completed');

// --- Persistence after a reload ------------------------------------------
await reloadPage();
await waitForText('Members', 30000);
await clickLabel('^Planner$');
await waitForText('Add task', 20000);
await sleep(1200);
await searchPlanner(title.toLowerCase());
await waitForText(title, 20000);
await sleep(1000);
const persisted = await pageText();
assert(/Completed/.test(persisted), 'The completed planner task is not under Completed after reload', persisted.slice(0, 900));
assert((await taskByTitle(title, adminLogin.access_token)).status === 'completed', 'The completion was not persisted');
await shot('e16-planner-persisted');

// Clean up.
await api('POST', '/tasks/bulk/delete', { task_ids: [created.id] }, adminLogin.access_token);
assert(!(await taskByTitle(title, adminLogin.access_token)), 'The E16 task was not deleted');

console.log('E16 PASSED: Planner urgency sections, inline creation, inline completion, persistence after reload.');
process.exit(0);

