11: class AuthService {
12:   AuthService(this._client);
13: 
14:   final ApiClient _client;
15: 
16:   /// Key used to persist the JWT token in shared preferences.
17:   static const _sessionTokenKey = 'session_token';
18: 
19:   /// Registers an account. The very first account becomes the active admin;
20:   /// later sign-ups must pick a project and start pending. A missing project
21:   /// surfaces as [ArgumentError] (server code `project_required`).
22:   Future<Account> signUp({
23:     required String name,
24:     required String email,
25:     required String password,
26:     String? position,
27:     int? projectId,
28:   }) async {
29:     final json = await _client.post('/auth/signup', {
30:       'name': name,
31:       'email': email,
32:       'password': password,
33:       'position': ?position,
34:       'project_id': ?projectId,
35:     });
36:     return Account.fromJson(json as Map<String, dynamic>);
37:   }
38: 
39:   /// Returns the account when credentials are valid and active.
40:   ///
41:   /// Throws [StateError] for unknown accounts, wrong passwords, and pending
42:   /// accounts awaiting owner confirmation. On success the session token is
43:   /// stored on the client and persisted to shared preferences.
44:   Future<Account> login({
45:     required String email,
46:     required String password,
47:   }) async {
48:     final json = await _client.post('/auth/login', {
49:       'email': email,
50:       'password': password,
51:     });
52:     final token = json['access_token'] as String;
53:     _client.setToken(token);
54:     SharedPreferences.getInstance().then((prefs) {
55:       prefs.setString(_sessionTokenKey, token);
56:     });
57:     return Account.fromJson(json['account'] as Map<String, dynamic>);
58:   }
59: }
